/* 2016年5月16日 文教委員会 会議録全文（正式会議録／公式会議録の転載）。scripts/minutes_fulltext.py で生成。 */
window.SHINAGAWA_DB.registerMinutes({"id":"h28-20160516-9","dateIso":"2016-05-16","title":"2016年5月16日 文教委員会","sourceType":"formal","sourceUrl":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=4882#one","fetchedAt":"2026-08-14","characters":45639,"voices":[{"i":1,"speaker":"塚本委員長","text":"○午後１時００分開会\nただいまより、文教委員会を開会いたします。\n本日は、お手元の審査・調査予定表のとおり、区立ひろまち保育園の視察を行った後、委員会を再開し、報告事項、その他と進めてまいります。\nなお、木村品川図書館長は、所用のため、本日欠席との連絡をいただいておりますのて、ご了承ください。\n本日も効率的な委員会運営に、ご協力よろしくお願いいたします。\n────────────────────────────────────────────\n１ 視察"},{"i":2,"speaker":"塚本委員長","text":"それでは予定表１、視察に参りたいと思います。\n本日は、本年４月に開設した区立ひろまち保育園の視察を行ってまいります。\n視察先の概要につきましては、車中で説明をいただく予定です。また、現地でも詳細な説明を予定しておりますので、委員および視察に同行される理事者の方は、この後すぐ第三庁舎２階駐車場のマイクロバスにお集まり願います。\n会議の運営上、暫時休憩いたします。\n○午後１時０１分休憩\n〔視察場所：区立ひろまち保育園〕\n○午後１時５０分再開"},{"i":3,"speaker":"塚本委員長","text":"ただいまから、文教委員会を再開いたします。\n────────────────────────────────────────────"},{"i":4,"speaker":"塚本委員長","text":"議題に入ります前に、理事者から発言を求められておりますので、ご発言願います。"},{"i":5,"speaker":"中島教育長","text":"それでは、私のほうから、お手元に配付させていただきました品川区立学校における生徒の事故についての報告をさせていただければと思います。\n去る５月９日、先週の月曜日、午後７時１９分、東急大井町線荏原町駅におきまして、本区立学校の８年女子生徒２名が電車に飛び込み亡くなるという大変痛ましい事故が発生いたしました。\n詳細につきましては新聞等で報道されているとおりでございますが、お手元の資料をご覧いただければと思います。\n発生の当日の状況につきまして、また、それを受けての学校の対応、そして教育委員会の対応ということで概要を記させていただきました。\n学校では、事故の翌日に臨時の生徒集会を開きまして、子どもたちに事実を伝えるとともに、養護教諭やスクールカウンセラー、また、センターのほうから派遣いたしました学校支援チーム「ＨＥＡＲＴＳ」等と連携して、生徒に対する心のケアに努めるということで、当該学年、そして所属していた部活動の全ての生徒に面談を実施いたしました。\nその後、在校生全員に健康調査を実施いたしまして、その内容に応じまして、カウンセラー等による面接を実施しております。\n本日の夕刻に臨時の保護者会を開催いたしまして、現状と今後の対応について説明する予定ではございます。\n私ども教育委員会といたしましても、この２人の尊い命が一瞬のうちに失われてしまったということにつきまして、まことに遺憾であり、二度とあってはならないことと大変重く受けとめております。既に緊急校園長連絡会を開催いたしまして情報の共有化を図りましたけれども、今後とも警察等の関係機関との連携を密にいたしますとともに、これまで以上に生命尊重の教育の充実を期してまいりたいと考えてございます。\n簡単で恐縮ではございますが、まず私のほうからご報告させていただきます。"},{"i":6,"speaker":"塚本委員長","text":"発言が終わりました。\n本件について、ご質疑等はございますか。"},{"i":7,"speaker":"飯沼委員","text":"ご報告ありがとうございます。大変な事態というところにおいては、亡くなられたお子さんはもちろん、ご遺族の方々、また周囲にいらしたお子さんや保護者の方、地域の方、あと教職員の方々、教育委員会も含め、また区の部局としてもこの事態を重く受けとめていらっしゃるとともに、本当にご心労の中でのこれからのいろいろ明らかにしていかなくてはいけないことだと思うので、とにかく今後、多くの方が、なぜ、どうしてという疑問をたくさん持っている中で、個人情報はもちろんあるかとは思いますが、でき得る限りの情報を、きちんと事実を伝えていただくという姿勢をまず持っていただきたい。今日は初めての報告なので１枚程度かと思います。幾つか質問をさせていただきたいと思います。\n名前とかはちょっとと言われておりますが、一貫校とか、そういった関係の言葉は特に、困りますか。\n１つは、新聞等の報道では、自殺かといった感じなのですが、自殺と断定をしていいのか。また、それの判断について。あと、やはりこの間は、中学生とか高校生、感じやすい年ごろのお子さんの自殺のところで、いじめの問題が取り上げられるのは常だと思うので、その辺の現状においての、どこまで調査が進んでいて、どう判断しているのかということを１点お伺いしたいのと、あと、今日の臨時保護者会なのですけれども、この内容は学年にかかわっているのか、全校の保護者の皆さんなのかということと、あと、ぜひ、私、区議会議員としては、地域の方から、私、当該の地域に住んでおります。ご質問をたくさんいただくので、外に伝えられることと伝えられないことの分別はついていると思うので、ぜひ保護者会に参加をさせていただきたいと思っていますので、その点についてもよろしくお願いいたします。"},{"i":8,"speaker":"熊谷指導課長","text":"まず、亡くなったお子さんのご冥福をお祈りしたいと思っております。\nさまざま面談ですとか、そういったところからは、新聞報道になされているとおり、いじめ等、また、特定の人間関係で悩んでいたという状況は見られてございません。まずそこのところをお伝えしたいと思います。\nそれから２点目の保護者会でございますけれども、それにつきましては、当該学年だけではなく、保護者全員に対して保護者会を実施していく予定でございます。"},{"i":9,"speaker":"塚本委員長","text":"出席に関してはどうですか。"},{"i":10,"speaker":"熊谷指導課長","text":"実は今日は、プレス等も含めて、お入りいただくことはご遠慮いただいております。というのは、保護者の方対象ということになっておりますので、それにつきましては保護者のみということでお願いしたいと思っております。"},{"i":11,"speaker":"飯沼委員","text":"ありがとうございます。\n先に、今日行われる保護者会のことなのですが、保護者のみに、プレスではないので、私たち、大事な文教委員会という議会の側の立場にいるので、ぜひ、こことここは注意してほしいという注意事項つきでも結構なので、ぜひ参加をさせていただきたいです。もしそれがだめな場合は、その場の内容も含めて、今後どのような報告を受けられるのかということを１つです。\nあと、面談から、いじめ、特定の人間関係で悩んでいたのではないという受けとめ方なのですが、今日いただいた資料の中では、部活動の生徒一人ひとりに対する面談を実施というところにおいてはわかったのですが、この２人のお子さんが同じクラスだったかどうかも把握の上でわからないので、関係しているクラスの子どもたちの状況が、その下に書いてある健康調査、これだけだったのかどうか、その辺の中身も教えてください。"},{"i":12,"speaker":"熊谷指導課長","text":"まず、学校の対応のところにございますように、１１日から当該学年、すなわち所属していた学年全員と、それから部活動、同じ部活動に所属しておりましたので、その部活動に所属しているお子さん全員に面談を行っています。\nまた、その後も子どもたちも非常に動揺する部分もございますので、カウンセリングということで、もう既にカウンセラーの面談を行っているところです。\nそれから、先ほど、自殺か否かということですけれども、これは報道にもありますように、警察からは自殺ということで出てございますので、捜査としてはそういった。ただし、事件性はないというふうに伺っております。\n報告ですけれども、今日は本当に保護者に対して初めて校長から説明をする会でございますので、保護者のみということでお願いしたいと思いますが、今日の内容につきましては、次回の文教委員会でご報告させていただきたいと思います。"},{"i":13,"speaker":"飯沼委員","text":"ありがとうございます。\n何点か意見も述べさせていただきたいのですが、今、カウンセリングから面談の後いろいろケアがされている、始まっているということなのですけれども、品川区の今の教育の制度からすると、広範囲のところからお子さんが通ってきているというところにおいては、実際にこの文教委員会では名前とかは触れないと言っても、実際、インターネット上では、全てもう明らかになっているというところにおいては、広範囲に影響が及んでいるし、やはり心配が広がっているというところにおいては、私たちは、ぜひ当該の学校の児童・生徒だけでなく、小学校のところも、出身校の周りでいろいろ声が上がっています。そういった意味では、広くケアを必要とされるお子さんを早くキャッチをして対応していただきたいということが１つお願いです。\nあと、ケアのところにおいては、保護者の皆さんとのお話は今日されるというところですけれども、こういう問題、本当に触れたくないとおっしゃる保護者の皆さんもいらっしゃるし、あと、朝も毎日送っていって、夕方も帰りを待っていて一緒に帰ってくるというお母さんもいらっしゃるというところにおいて、保護者の方々へのケアももちろん重要であるし、また、私はすごく心配しているのは、以前の自殺のケースにおいて、やはり深くかかわっていた教職員の方のケアも本当に本当に大事なことである、きちんと立ち直れるような状況にしていただきたいという思いがあるので、そこのところは本当に力を入れていただきたいと思います。いかがでしょうか。"},{"i":14,"speaker":"村尾教育総合支援センター長","text":"子どもたちの心のケアということで、広範囲にということで今お話をいただきました。教育委員会のほうから、全ての学校を対象に、翌日５月１０日から、子どもの欠席状況を全て確認いたしました。１０日以降、連続して休んでいる子がいないか、また、何らかの形で心配とか相談があれば、そのような形の有無を確認をさせていただき、今のところ、大きな問題はなかったというふうに思っています。\n同時に次の日には、荏原町駅周辺の学校の校長先生にお願いをして、特に近くを通ったりする子もいますので、その辺で子どもたちの様子を十分見ていただいて、もし何かあれば、都費のスクールカウンセラー、また緊急であれば区のカウンセラーを派遣できるということで、今、体制をとっているところでございます。"},{"i":15,"speaker":"熊谷指導課長","text":"教員に対するケアでございますが、その翌日から都のアドバイザリースタッフという緊急対応を行う心理士が入りまして、先生方のケアにつきましても行っています。また、産業医等もお願いして実際に対応しているところでございます。"},{"i":16,"speaker":"飯沼委員","text":"ありがとうございます。\n二度と起こらないということと、やはり後に活かされる対応というところで、十分でき得る限りのことをしていただきたいと思っています。\nあと、ぜひこういった問題を、起きてはならないけれども、起きてしまった後に活かしていくという意味で、教職員の方々が、自分の学校だけでなくて、よその学校で起きた事例について、ぜひ共有をしてほしいと思うのです。そういった意味で、私はすごく今、職員会議が不十分であるという声を聞いているのですが、職員会議が１回どのくらいで何回ぐらい行われているのかということもお伺いしたいのですが、ぜひ学校を超えて事例を共有してほしいのと、やはりよりよい事例が必ずあると思うのです。そういうものを十分に生かした全体のものにしていただきたいと思うのが１つです。\nあと最後なのですが、調査がまだこれからだと思うのですが、今、現状がどこの調査まで行って、今後どういうふうな調査が続けられていくのかと思うのと、教育委員会のところだけで完結するものなのか、いじめ防止対策推進条例などだと区長部局のほうの調査委員会ともかかわってくるのですが、その辺がどういうふうに今後見通しとしてなるのか教えてください。"},{"i":17,"speaker":"熊谷指導課長","text":"先ほどもお話ししたように、いじめの徴候が全くない、いじめで悩んでいた様子が見られなかったということ、それから保護者の方のお気持ちもございますので、現段階で調査を続行するということは考えておりません。\nですので、まずは保護者の気持ちを大切にしてということで、ご遺族のお気持ちを大事にした上で行っていきます。今はとにかく特定の人間関係、いじめ等の要素が見られなかったということを再度お伝えしたいと思います。"},{"i":18,"speaker":"品川庶務課長","text":"この事件の翌日、５月１０日ですけれども、総合教育会議も行いまして、区長と教育委員で、この事件に関しての情報共有をしている状況でございます。"},{"i":19,"speaker":"村尾教育総合支援センター長","text":"区内の全ての学校の教職員の皆さんへという部分につきましては、先ほど、教育長が申しましたとおり、すぐに臨時の校長会を開きまして、各学校で改めて、各学校の子どもたちの状況の把握等に努めるとともに、今後、生活指導または養護教諭等、さまざまな場面で今回のこの事故を受けて、それぞれ各学校で改めて考えていかなければいけないこと、また、進めていかなければいけないことについては、こちらのほうで推進していこうというふうに考えているところです。"},{"i":20,"speaker":"伊藤副委員長","text":"端的に確認しますけれども、いじめが原因と見られる案件が過去にあって、それは、さまざまなルールやプライバシー、個人情報等も十分配慮した上で詳細の報告をいただきました。なので、今日のこの会で構わないけれども、いろいろな方々がいろいろな意見をおっしゃって非常に混乱するし、大きな話題になる可能性のある案件なので、情報の取扱いに十分注意しながら、内容を確定した後に、正しい情報を議会に適切な場で報告をしていただきたいと思うのですが、いかがでしょうか。"},{"i":21,"speaker":"本城教育次長","text":"先ほども少しご答弁させていただきましたが、今日まさに保護者会ということで、直接保護者の方に対して校長先生のほうからお話をさせていただくということでございますので、それも含めて、今後のこの文教委員会におきまして、保護者会を含めた経緯の報告という形で、何らかの形で、より全体がわかるような報告をさせていただければと考えているところでございます。"},{"i":22,"speaker":"伊藤副委員長","text":"要望だけしますけれども、こういう重篤な案件ですと、いろいろなうわさが出たり、それからいろいろな思いでお話しされることがたくさんありました。過去のことも。だから、そんなことで無用なこの、できないわけであって、プレスが教育委員会から正しい情報をつかんで、それを処理をして判断をして、しかるべき時期に議会に報告をする。それを聞いた私たちが、またさまざまな活動をしていくことが私は正しいと思っていますので、そういうふうに進んでいただきますようお願いしておきます。よろしくお願いします。"},{"i":23,"speaker":"石田（ち）委員","text":"私も街頭などに立っていますと、地域の方から声をかけられるわけです。品川は今、施設一体型、また分離型とあるわけですけれども、その方は、校名も出して、そして一体型か分離型かということも出して問いかけてくるわけです。私も詳細はまだ詳しいことはわかっていないので何もお答えできませんというふうにお答えするのですけれども、もう地域の方は知っています。テレビのニュースなどでも、校名は伏せられているのですが、その学校の外壁などが出されているわけです。あの学校なのだということで、もう皆さん、当然知っているという形で声をかけられるわけです。\nですので、やはり今ここでそういった名前を伏せるというのは、理解をしないわけではないのですが、裏にこれだけ大きな事故が起きているところですので、こういった教員の多忙化だったり、また、学校の格差というのでしょうか、大規模化、小規模化とこういった問題もある中で、しっかりと検証していかなければいけないと、私、本当に重く受けとめています。教育委員会としては、まだ今は名前を出せない状況かもしれませんけれども、今後こういった検討を進めていくという姿勢を持っていただきたいと思うのですけれども、いかがでしょうか。"},{"i":24,"speaker":"熊谷指導課長","text":"報道なのですけれども、警視庁からも一切学校名は出さないということで、それはすり合わせをしています。なぜならば、今いるお子さんたちの正常な学校生活を守るためにも、警察は学校名を出さないということで出していませんので、それをお伝えしておこうと思います。"},{"i":25,"speaker":"塚本委員長","text":"今後の区の方向性というか、取組みについて述べられるところがあれば。現時点でということでしょうけれども。"},{"i":26,"speaker":"中島教育長","text":"先ほど、教員の多忙化、それから学校の格差、こういったようなもの等を含めた総合的な検討をすべきではないかというお話がありましたが、今回の事故に、例えば教員の多忙化ですとか、学校の格差がどのようにかかわっているかというものは検証できるものではないと思いますし、私どもは、今回の大変痛ましい事故ではございますけれども、これの原因等に関しましては、実際問題といたしまして、新聞報道で出されているような状況、個人にかかわるそういった状況であるという判断に至っておりますので、それをまた今後、調査し、学校生活のさまざまな部分の中で状況を検討していくということは現在は考えておりません。"},{"i":27,"speaker":"鈴木（博）委員","text":"この２人の女子中学生の方は非常に痛ましい結末を迎えて、心からお悔やみを申したいと思いますが、一般論として考えてみると、このぐらいの年齢の思春期の女性は、女性に限らず男もそうですけれども、自殺があったとか、自殺未遂とか、そういう案件は決して少なくないような気もする。だとすると、一番何が大切かというと、その本人もそうなのですけれども、結構その後、後追い自殺が起こることがままあるというような話も聞きますので、だから、静かな環境で、できるだけご遺族の方と、当該学校およびその地域の方の心にさざ波を立てないような、十分心情に配慮した上で正確な原因の究明とか、環境の状況の分析とか、後追いを防ぐような周りの方の心のケアとか、その辺をしっかり教育委員会のほうにお願いしたいと思います。これは要望です。"},{"i":28,"speaker":"高橋（し）委員","text":"今、鈴木博委員のほうからお話があったこととあれですが、痛ましい出来事ということなので、いわゆる自死の連鎖がどの年代の子どもでも必ず起きて、より大きな問題になってしまうので、今、鈴木博委員からお話があったように、負の連鎖ではありませんけれども、そういうことがないように十分、今後の指導をよろしくお願いしますということで、いわゆる命の大切さというか、そういったことを含めて、ぜひ区内の小学生、中学生にお伝えいただければと思います。"},{"i":29,"speaker":"大倉委員","text":"今、皆様からお話がありましたとおり、子どもたちのこういった痛ましい事故が次に起こらないようにというところで、どうやって子どもたち全体を品川区の学校として守っていくか。例えば、今回の２人で手をつないでというところでは、そういった多感な時期の子どもたちの感性の中での共感ということで、他人の悩みを自分の悩みのように捉えて、こういった自殺とかになってしまうという、なかなか表に出にくい部分が相当あるのかなというところで、例えばゲートキーパーのような、しっかりと変化に気づけるとか、子どもたちをそういった、少しでも「んっ？」と思ったときに対応できるような体制を今後どうやって、これをしっかりとっていかなければいけないと思うので、その辺をどうやって考えているかということを教えていただきたいのと、あと、報道等でも先ほどもありました外観が映っているとか、あとはその当該学校の前の報道陣の方とか、いろいろな方々が車をとめて校門の前とかにいるという状況があるというふうに聞いているのですが、その辺はどういうふうに対応していくのか、できるのかというところを教えてください。多分、子どもたちも、保護者の方たちも、かなりそういうものを見ると心配になるし、不安になると思うので、その心配、不安をあおるような形にならないように対応していただきたいと思いますが。"},{"i":30,"speaker":"熊谷指導課長","text":"やはり子どもたちの心の闇といいますか、見えない部分、特に思春期のお子さんたちにはさまざまな大人には見えない部分があると思います。ですので、そういったものについて、非常に小さな変化等にも見抜けるような教員指導力ということもこれから一層身につけなければいけないと思いますし、そういった部分では研修等も必要になってくると思います。また、実際になかなか見づらいところ、これまでにはなかった部分、さまざまな子どもたちの心の変化ということも時代によって変わってくるところもあろうかと思いますので、そういったことについても対応できるように、また研修等でしっかり教員の指導力を高めていきたいと思っています。\n報道については、教育総合支援センター長からいたします。"},{"i":31,"speaker":"村尾教育総合支援センター長","text":"報道関係につきましては、まさに学校の周りに当初すごく多くの方がいらっしゃいました。ただ、区といたしましては、品川ニュースということで、基本的にはマスコミにプレスリリースをかけるようにということで対応してきました。その結果、金曜日、土曜日、日曜日については、学校の周りには報道機関が来ていなかったということ。それから、本日、保護者会が１９時から行われますけれども、終了次第、１時間後に、その内容についてはきちんとお伝えするということで、学校としては、やはり子どもたち、通常の落ち着いた学校生活に戻したいということをマスコミの方にお願いをしてご協力をいただく、またご理解いただく、そのような方向で考えているところです。"},{"i":32,"speaker":"浅野委員","text":"今回このようなことになりまして本当に残念でならないというふうに。ほかの報道ですけれども、子どもたちがやはり心の変化ですとか、気持ちの荒れる時期ということで、例えば、新しい学年になるとか、また今回みたいにゴールデンウィーク、長い休みの後、これは多分、夏休みとか冬休みだとかいろいろなケースが考えられる中で、今回、そのようなことも想定されて、例えば子どもたちに、直接的には難しいかもしれないけれども、気をつけるような伝達でありますとか、また、親御さんに対しても、こういうことに気を配ってもらいたいとか、そのような連絡は、これまでされたことがあるのか、それとも今回の件を通じて何らかの対策をとっていこうとしているのか、それについて教えていただきたいと思います。\nそれと、５月９日午後６時２３分から時系列で出ているのですけれども、その中でやはりちょっと気になるのが、このように情報が入ってくる中で、警察から学校へというものと、夜遅くなってから荏原警察から指導課とあるのですけれども、このような事件にしろ事故にしろ、さまざまな問題が発生する可能性がありますけれども、そういうときの危機管理体制というのでしょうか、そのような動きはどうなっているのかということを教えていただきたいと思います。\nそれとあと、順番です。やはり学校が先になるのかとこれだと見受けられるのです。教育委員会の指導課がその後ということになっていますけれども、このような流れは普通の流れなのかどうかということについても教えてください。"},{"i":33,"speaker":"村尾教育総合支援センター長","text":"まず１点目の自殺関係についての予防の取組みでございますけれども、昨年度以来、事あるごとに生活指導の部分で、いじめも含まれていますけれども、自殺予防ということで、各学校に通知をし、特に各学校で気になる、また配慮の必要な児童・生徒については、十分担任、また家庭と連絡をとり対応するような取組みをしてきております。\nまた、新聞報道で昨年９月１日は大変自殺の件数が多いということもありましたので、夏休みの始まる前にも各学校に改めて自殺予防ということで取組みはこれまでも進めてきております。４月、９月、１月等、特に学期の変わり目とか、子どもたちの生活がちょっと変わるという部分については、これまでも十分注意するようにはしておったのですけれども、今後もこの辺については各学校を含めて、より一層生活指導、また、子どもたちの様子の確認を進めていこうというふうに考えているところです。"},{"i":34,"speaker":"熊谷指導課長","text":"まずは警察から当該のお子さんのいる学校に連絡が入ることになっています。そこから必ず私ども教育委員会に情報提供が入ります。この中で荏原警察から指導課にということで、１０時５０分、プレスが出ますということの連絡が入ったとありますけれども、この前にこちらから荏原警察に一報を、学校の情報を踏まえて連絡を入れていますので、それを受けて、いよいよ午後１０時５０分に、こういった内容で出ますというご連絡をいただいたということであります。ですので、基本的には学校を通じて教育委員会に情報が上がってくる。例えば、夜間ですとか、早朝ですとか、そういったときには、私どもの連絡先を全て校長に伝えていますので、携帯等に連絡が入るようになってございます。"},{"i":35,"speaker":"浅野委員","text":"ありがとうございました。\n子どもたちの心の変化に対しての対応ということでされているということですので、これも引き続き取り組んでいただければと思います。\nあと、危機管理体制は、例えば手順とかがある程度決まっていると思うのですけれども、もしその概要を、極めて簡単で結構ですので、どこが一報が入る、そうした場合に、これは事件、事故とかいろいろあると思うのですけれども、どういう体制で教育委員会の中に入ってくるのか。区長部局のほうにもどういう形で入っていくのかということについて、簡単に教えていただけますか。"},{"i":36,"speaker":"熊谷指導課長","text":"まず学校から教育委員会の指導課もしくは総合支援センター、どちらかに入ってきます。その上で区長部局には、今回は次長が横にいらっしゃったので、次長から全部連絡を入れていただき、基本的にはすぐに状況について区長部局に入れていくことになっております。\nそれを受けまして、都のほうにも生活指導班というところがございますので、状況について、ある程度把握ができたところで入れていくという流れになっています。\nそのときそのときの状況によって、上げていき方ですとか、どこまで伝えるかという範囲については異なってきますけれども、基本的には教育委員会事務局に一報が入って、そこから区長部局等に連絡が入っていくという流れでございます。"},{"i":37,"speaker":"浅野委員","text":"ありがとうございました。"},{"i":38,"speaker":"飯沼委員","text":"今、自殺予防のところで、各学校とか教育委員会でもまたいろいろ研修などもされていらっしゃるのは当然と思いますけれども、具体的にどんな中身なのかを教えていただきたいのは、いじめにかかわらず、自殺は全体的に数は減っているけれども、子どもが減っている中での割合では、結構増えているというところを見て、文部科学省で幾つか出しているものがあったので、手引きなども見てみたのです。こういうものがどのように使われているのかと思ったもの。\n１つは、子どもの自殺予防、関心は必ずしも高くはないといえるという書き方をしているのと、自殺は孤立の病と呼ばれていて、子どもは、常に言われていますけれども、助けてほしいという発信をしているはずであって、それをいち早くキャッチをするのは、受けとめるのは、ゲートキーパーとしての教職員集団であるという書き方もしていまして、やはりその辺の協力体制、また、今の学校の品川区のコミュニティ・スクールなども含めると、周りの方々も含めた協力体制をどうつくっていくのかということが、本当に一番に問われていくと思うのです。そういった意味においては、私は一番にはゲートキーパーである先生たちが、その職場でどう話をするのか、それをどうつなげていくのかというところが本当に重要である。さっき、職員会議のことも伺ったので、そこの辺も含めて、ぜひぜひそこのところを構築していただきたいと思うことを最後の質問といたします。よろしくお願いします。"},{"i":39,"speaker":"村尾教育総合支援センター長","text":"子どもたちの自殺防止の取組みということで、例えば本年度に入りましては、４月５日の時点で、児童・生徒の自殺防止の取組みの徹底ということで、私、区のほうから各学校に通知を出させていただいております。その中には、入学式や始業式等で、子どもたちが悩みや不安がある場合は、教職員に相談するようにすること、また、各学校にスクールカウンセラーがいますので、そことのパイプをきちんとつなげるように等々、通知を出させていただいているところがあります。\nまた、同じく４月１８日には、相談窓口ということで、東京都のいじめホットラインを含めて、関係機関の電話番号等も各学校に配付し、子どもたちに周知をしているところがございます。\nまた、昨年の３月末の時点で、子どもの様子、見守りチェックリストということで、多分その資料と同じようなものがあるかもしれませんが、子どもの様子の変化ということで、特に命の危険が迫っている際の変化ということで、チェックリストを各学校に配付し、気になることについては直ちにチェックをし、すぐに管理職に報告をするようにというようなことで、さまざまな取組みはしております。ただ、今回の件におきましては、改めて私どもも、このような体制を検討を進めていこうというふうに考えています。"},{"i":40,"speaker":"飯沼委員","text":"一言。ぜひ力を入れてやっていただきたいのですが、現場の教職員の方々からは、なかなか見えてこない、重要な中身なのだけれども、ぜひ共有をしたいのだけれども、なかなか見えないという声が届いています。だから、仕組みはあるのだと思うのですが、そこでやはり一番子どもたちに身近にいらっしゃる方々の声を忌憚なく出してもらえるような、一番には私は各学校の職員会議だと思いますし、それを拡大していくような取組みをぜひぜひお願いしたいと思いますので、これはお願いでよろしくお願いいたします。"},{"i":41,"speaker":"塚本委員長","text":"ほかにご発言はございますか。\n〔「なし」と呼ぶ者あり〕"},{"i":42,"speaker":"塚本委員長","text":"ほかになければ、本件は以上で終了いたします。\n────────────────────────────────────────────\n２ 報告事項\n(1) 平成２８年度新入学学校別増減要因一覧について"},{"i":43,"speaker":"塚本委員長","text":"それでは、予定表２、報告事項を聴取いたします。\n初めに、(1)平成２８年度新入学学校別増減要因一覧についてを議題に供します。\n本件につきまして、理事者よりご説明願います。"},{"i":44,"speaker":"有馬学務課長","text":"それでは、平成２８年度新入学学校別増減要因一覧について、ご説明いたします。資料は、学務課、Ａ４のペーパー２枚になります。\nこの資料ですけれども、１ページは、小学校および義務教育学校（前期課程）の１学年について、２ページ目が、中学校および義務教育学校（後期課程）、７学年について、それぞれ前年１０月１日の住民基本台帳上の新入学予定者の人数、つまり、学区域内の児童・生徒の数をもとに、翌年４月までのさまざまな増要因、減要因を加味し、表の一番右に示してありますけれども、平成２８年度４月１日現在での入学者数を学校ごとに一覧に示したものでございます。\nまず１ページ目ですけれども、例えば小学校の１番、城南小学校の平成２７年１０月１日の登録者数９３とありますけれども、これが住民基本台帳上に記載のある通学区域内の子どもたちの人数、１０月１日付という形になります。\nその右、大きく増要因となっておりますけれども、まず希望申請の入学者とは、学区外から学校希望選択を希望し、この例でいきますと、実際に城南小学校に入った人数で１５人ということでございます。\nその隣の指定校変更は、就学指定通知により一旦決定された学校を変更するもので、区内転居やブロック外の学校を希望して入学した人数という形になります。\n区域外就学は、入学時には区外に住んでいて、転入届はされてはいないけれども、これから品川区内に住所を移すという明確な予定がある。例えばマンションを購入して契約書があるというような方となります。\n転入は、１０月１日以降に区外から転入してきた人数でございます。\nその他ですけれども、これは主に大使館、領事館などに勤務する職員の児童で、住民登録のない、在留資格の要らない外国人、外国籍で入学された方および日程のずれなどによって、データ処理上、若干人数調整をした分をこの中にカウントしております。\n次に、減要因でございます。学区外へ申請入学者とは、学校選択希望申請をして他の学区の学校に入学した児童数になります。学校選択希望申請をしたけれども希望する学校に入れなくて戻ってきたというようなケースは、ここにはカウントしておりません。実際に抜けた人数という形になります。\n城南小学校で言えば２６人の減となっております。この２６人は、別の学校で増要因としてカウントされることになります。したがいまして、増要因の希望申請の入学者の合計数の欄と、減要因の学区外へ申請入学者とは、入と出の関係となりますので、表の一番下の合計欄に示したとおり、同数の６３９という形になります。\n次が、国公立、私立の学校へ入学したことにより減となった人数です。\nそれから、指定校変更ですが、これは就学指定後に同じように転居やブロック外の学校へ変わった人数になります。\n学校選択の希望申請入学者と同様に、指定校変更の人数も入と出、両方カウントいたしますので、合計欄の数字は１３０人増えて１３０人減ったというような関係になっております。\n区域外就学は、４月までには区外へ引っ越す予定があるということで、区外の学校へ就学する人数です。転出は１０月１日以降、区外へ転出した人数です。\nその他ですけれども、主な内容は、特別支援学級の固定級への入学者、あと、若干、データ集計上の調整分が入ってございます。\n表の一番下の合計欄をご覧ください。平成２７年１０月１日現在の住民基本台帳では２,８０８人でございました。前年と比較し１３７人の増。そして最終的な入学者数は、一番右の欄になりますけれども、２,５９７人で、昨年と比較し１０４名の増となっております。\nなお、希望申請による入学者は６３９人で、住民登録者の２２.８％、昨年より２.７ポイント下がっております。\n学校別に見ますと、８番、第三日野小学校と、２５番、第二延山小学校につきましては、結果として希望申請による受入れの実績はありませんでした。\nまた、３１番の小山台小学校では、区域外への申請入学者の実績もゼロとなっております。\nまた、いわゆる小規模校につきましては、それぞれ昨年の新入学生を上回っている状況でございます。\nその他は、ほぼ例年どおりで大きな傾向の変化はございません。\n続きまして２ページ目をご覧ください。中学校・義務教育学校（後期課程）の表の見方は、基本的に同じでございます。\n一番左側が住民登録基本台帳登録者数、それから増要因の希望申請の入学者は通学区域外から学校選択を希望して入学した人数でございます。\n指定校変更は、就学指定通知発送後、申請に基づき変更基準に照らして認めたもの。それから区域外からの就学、区外からの転入となります。\nその他は、主なものとしては、小学校と同様、外国人等でございます。\n次に、減要因の学区外への申請入学者は、通学区域外の学校へ希望入学し、実際に入学した人数でございます。\n例えば、東海中学校で申し上げますと、５６名が違う公立の中学校へ入学しているという形になります。\nその隣は、区立中学校を選択せずに国公立、中等教育学校、私立へ進んだ人数。\nそして指定校変更は、就学指定をした以降に他の学校へ変わった人数となります。\n区域外就学、転出ということで、これはいずれも区外へ出ているものです。\nその他につきましても、内容は小学校と同様、主な要因といたしましては、特別支援学級へ進学でございます。\n中学校・義務教育学校の後期課程の結果でございますけれども、表の一番下をご覧ください。平成２７年１０月１日現在の住民基本台帳では２,３４３人、前年と比較し１０８人の増、これに対して最終的な入学者数は、表の右下、１,５８８人で、昨年と比較し４１人の増となっております。\n希望申請の入学者は７２１人で、住民登録者の３０.８％で、昨年より３.０ポイント下がっております。\nまた、減要因の国公立、中等教育学校、私立の合計は７２４人、３０.９％で、前年より１.２ポイントの増となっています。\n個別の学校の傾向といたしましては、入学者が昨年と比較して、浜川中学校と東海中学校で増となった一方で、品川学園で減となっております。その他の中学校については、おおむね前年並みで推移しているところでございます。"},{"i":45,"speaker":"塚本委員長","text":"説明が終わりました。\n本件に関しまして、ご質疑等がございましたら、ご発言をお願いします。\nよろしいでしょうか。"},{"i":46,"speaker":"飯沼委員","text":"１点だけお伺いしたいと思います。\n増減は、地域の小学校、中学校、また義務教育学校のバランスによっていろいろな状況が生まれると思うのですが、おおむねは前年とあまり変わらないという評価でよいのか、もう一回お伺いしたいのと、１点、荏原平塚学園のところは、７年生での学区外申請入学者が１４３名と多いのです。この生徒たちは、どの辺を選んで行っているのかということがわかったら教えてほしいのと、この辺、７年生で学校が変わるという要因が何かを捉えていらっしゃるのかどうか教えていただきたい。"},{"i":47,"speaker":"有馬学務課長","text":"まず、全体のバランスの傾向でございますけれども、今回は、小学校の場合、住民基本台帳上で１３７人増えているということで、中学校の場合も、住民基本台帳上で１０８人増えているというようなことがありまして、ここの増えているところの学区は、基本的に自分の学校の区域内で増えているというような傾向がまず１つ特色としてあります。\nそれから、荏原平塚学園で学区外へ１４３人という非常に多くの方が抜けているということでございますけれども、これは一貫校ではありますけれども、もともとここには平塚小学校の区域がそのまま荏原第一中学校に行くというようなことがございまして、その傾向が今でもあるということで、要するに、幾つかの小学校が１つの中学校に行くのではなくて、そこの学校からそもそも２つの中学校があったというようなことですので、兄弟がもともと荏原第一中学校に行っていたとか、親が荏原第一中学校に行っていたとかというようなことが１つの特色として、ここは荏原平塚学園から荏原第一中学校に多く流れているという傾向があるということでございます。"},{"i":48,"speaker":"塚本委員長","text":"ほかにご発言ございますか。\n〔「なし」と呼ぶ者あり〕"},{"i":49,"speaker":"塚本委員長","text":"ほかにご発言がないようですので、以上で本件を終了いたします。\n────────────────────────────────────────────\n(2) 平成２７年度品川区立学校における体罰等の実態把握について"},{"i":50,"speaker":"塚本委員長","text":"次に、(2)平成２７年度品川区立学校における体罰等の実態把握についてを議題に供します。\n本件につきまして、理事者よりご説明願います。"},{"i":51,"speaker":"熊谷指導課長","text":"それでは、平成２７年度品川区立学校における体罰等の実態把握について、ご説明いたします。お手元の資料に沿ってご説明申し上げます。\n１番は調査の概要でございます。\n(1)調査の趣旨につきましては、ご覧いただければと思います。\n(2)調査対象は、品川区立小学校３７校、中学校１５校、全５２校でございます。\n(3)調査内容でありますが、平成２７年度内に発生した体罰、不適切な指導、これらを「体罰等」といいます。またはその疑いがある事案の実態でございます。\n(4)調査方法でございますけれども、今まで同様、教職員は校長による聞き取り調査、必要に応じて指導課長等による聞き取り調査。また、児童・生徒には質問紙の調査を実施しまして、必要に応じて校長による聞き取り調査を行っているところでございます。\n(5)の調査対象期間でございます。調査は、平成２７年４月１日から平成２８年３月３１日までに発生した体罰等を対象とし、各学校において、平成２８年１月２５日から２月１０日までの間に実施しております。なお、調査期間以降に発生した案件につきましては、随時追加をすることになっております。\n次に、２の報告数でございます。\n(1)の学校別報告数の最後の行に、本調査への報告数とございます。こちらをご覧ください。括弧内に記されている件数で述べますと、小学校が１８件、中学校が２０件で、合計３８件でございます。\nちなみに、前回、平成２６年度の件数でございますが、小学校が１８件、中学校が９件、合計２７件でございました。\n(2)の申告者別報告数でございます。教員本人による申告は、小学校が１１件、中学校が８件。他の教員からのものが、小学校ゼロ件、中学校５件。児童・生徒本人については、小学校１３件、中学校１５件。他の児童・生徒からの報告は、小学校３件、中学校１２件でございます。保護者からは、小学校が２件、中学校が７件です。その他の１件は、いじめ早期発見システム、いわゆるアイシグナルへの匿名による通報でございます。これらの合計件数は、一番下にございますが、小学校で３０件、中学校で４７件、合計７７件になります。\nちなみに、昨年度の合計ですが、小学校が２３件、中学校が１４件の合計３７件でございました。\n続いて、２ページでございます。裏面になります。３番、報告の内容でございます。\n1)体罰でございますが、本年度につきましては、小学校、中学校ともにゼロ件でございます。\nちなみに、昨年度については、小学校で１件の体罰がございました。本調査は、平成２４年度から始まって４回目でございます。体罰の件数につきましては、平成２４年度が８件、平成２５年度が３件、平成２６年度は１件というふうに年々減少し、平成２７年にゼロ件となっております。\n2)番の不適切な行為につきましては、表の下に分類例をお示ししてありますので、ご参照いただければと思います。\nもう一度、表に戻ります。2)のアの不適切な指導については、括弧内の件数で述べますと、小学校４件、中学校が１２件、合計１６件。\nちなみに昨年度は、小学校３件、中学校が３件、合計６件でございました。\nイの暴言等でございますが、小学校は４件、中学校は４件、計８件でございます。\n昨年度の件数は、小学校が１件、中学校が１件、計２件でございました。\nウの行き過ぎた指導もゼロ件でございます。\nなお、昨年度もこの行き過ぎた指導につきましてはゼロ件でございました。\n3)の指導の範囲内以下はご覧いただければと思います。\n２ページの下のほうにありますけれども、(2)報告のあった事案のうち体罰以外と判断した事案例は、全部本区の事例でございます。お読みいただければと思います。\n続きまして、３ページをご覧ください。昨年度までは、このページに体罰と判断された事案につきまして、行為者別、場面別の内訳や事案の詳細について記述いたしましたが、昨年度につきましては、体罰と判断された事案がありませんので、内訳表などを除いてございます。\n４番、体罰の根絶を図るための取組でございます。\n(1)学校への指導。(2)学校組織としての意識向上。(3)教職員研修の充実。(4)通報システムの活用・周知徹底。(5)体罰根絶ＤＶＤ「ＳＴＯＰ体罰」の活用促進。(6)学校における体罰防止に向けた取り組みの強化といったことでございますが、(1)、(3)、(4)、(5)につきましては、昨年度に引き続き、今年度も同様に取り組んでまいります。\nまた、(5)で示しましたＤＶＤですが、これは教職員のみならず、保護者、児童・生徒へも視聴させ、体罰に対しての問題意識、注意喚起を図って、何かあったりしたときには、迷わず周囲と相談できるようなことにすること。あわせて品川区の場合は、いじめ等で設置している目安箱、またセンターの直通専用電話、アイシグナル等で、体罰をなかなか学校の先生に相談することができない内容につきましても、これらの相談システムを使って相談するようにということをあわせて周知徹底してまいるところでございます。\n昨年度の新たな取組みといたしましては、(2)の学校組織としての意識向上でございます。「体罰０宣言」をするにあたり、教職員間でスローガンと具体的な取組内容３点を決定し、「体罰０宣言ポスター」に直接書き込んで、完成したポスターを掲示し、学校組織として意識の向上を図るという取組みであります。\n３ページの下側に、学校における具体的な取組事例を紹介させていただいておりますので、ご覧いただければと思います。\n最後になりますが、体罰の発生件数は、先ほど申し上げたとおり、８件、３件、１件と減り、今年度ようやくゼロ件を実現いたしました。しかし、残念ながらその一方で、不適切な指導、暴言等につきましては増加傾向が見られるため、引き続き気を引き締め、体罰等が根絶するように全力で取り組んでいく覚悟でございます。"},{"i":52,"speaker":"塚本委員長","text":"説明が終わりました。\n本件に関しまして、ご質疑等ございましたら、ご発言をお願いします。"},{"i":53,"speaker":"石田（ち）委員","text":"今お話が出たので、体罰はゼロ件ということでしたけれども、不適切な行為のところは増えているということを、区としてはどのように見られているのか、どうしてこういうことになるのかということをどのように説明していかれるのかということ。\nそれから、２ページ目の(2)の体罰以外と判断した事案例を見ても、ひどいなとちょっと感じるのです。体罰ではない、不適切な行為ということなのですけれども、やはりこれを受けた生徒としては、体罰と感じるのではないかと思うのですけれども、これが不適切な行為になるのはなぜなのかということを伺いたいと思います。"},{"i":54,"speaker":"熊谷指導課長","text":"この不適切な行為につきましては、やはり引き続き教職員の意識を高めていくということが必要だと思いますし、絶対にあってはならない行為だと思いますので、これまで以上に教職員の意識を高めるよう、各学校で指導を徹底していきたいと思っています。\nなお、ご質問がありましたこの不適切な指導につきましては、これは都の教育委員会の人事部が、これは不適切な行為であるということで判断しておりますので、これにつきましては、私どものほうから不適切な指導ということで上げているものではなく、判断を下したのは東京都の人事部ということになります。"},{"i":55,"speaker":"石田（ち）委員","text":"体罰はないけれども、不適切な行為が増えているというところで、教員の意識を高めていくということでしたけれども、本当にあってはいけないことなのですけれども、やはり教員の皆さんの中でも、日々の忙しい職務の中で、何か原因があったのかと私も感じてしまいます。小学校に通う子どもたちなどからは、先生が忙しいから相談できないということも言われたりもするのです。ですので、親も子どもたちも教員の多忙化を知っているという状況のもとで、教職員の皆さんの意識を高めていくというのはわかるのですけれども、どうしてこういうふうになったのかということを、根絶のためということで３ページにあると思うのですけれども、研修、研修、研修ということで、教員の皆さんは本当に大変だなというふうに、ここでもまた改めて思うのですけれども、一人ひとりの教員の皆さんに心を寄せた聞き取りだったり、そういった形はとられているのか、本当に多忙ですので、子どもたちと向き合う時間もないほどという状況ですので、そういったところを配慮した上での調査というのでしょうか、研修、研修ではなくて、そういった対応を増やしていただきたいと私は思うのですけれども、いかがでしょうか。"},{"i":56,"speaker":"熊谷指導課長","text":"たとえどんな理由があったとしても、決して体罰は認めるわけにはいきません。絶対に、子どもたちの心を傷つける体罰は、いかなる理由があっても、それは認めるわけにはいかないと考えております。\nまた、多忙ということがございますが、教員は忙しいからといって体罰を引き起こすわけではない。どんなに忙しくても、体罰につながるということは絶対に認めてはいけないというふうに思っていますので、これにつきましては、今後とも引き続き厳しく指導をしていきたいと思っております。"},{"i":57,"speaker":"浅野委員","text":"今回の調査、報告を拝聴するのですけれども、１つ気になったのが、(2)の報告のあった事案のうち体罰以外と判断した事案例というところなのですが、２つ目の暴言等とあります。これが体罰以外ということなのですが、区として、この暴言というのは体罰以上の影響を子どもたちに与えるということは、当然、教育委員会の皆さんはご存じだと思います。私も小学校などで、これは先生というよりは、いじめの中で、一人の女の子が集中攻撃を浴びまして、６年生のときでしたけれども、卒業せずに転校していったという、私にとっては本当に残念なことが過去にありました。もしかすると、暴言というのは体罰以上に子どもたちを傷つけたりとか、そういう可能性は大きいと思うのです。ふだんから多分この件につきましても、教育委員会としては発生をしないように取り組んでおられると思いますけれども、例えばそれが発見されるとか、そういうようなことは過去にあったかと思いますけれども、もし事例があれば教えていただきたいのと、これが発生した場合に、どのような対処をしていくのか、今回の報告の中にも含まれないということになっているので、少し気になって質問させていただきますが、よろしくお願いします。"},{"i":58,"speaker":"熊谷指導課長","text":"今、委員からもご質問があったように、暴言というのは、非常に子どもの心を傷つけ、また、それがいじめにつながっていく原因にもなるものであると考えます。こういったものは、子どもたちから教員にこういった話があったというようなことが上がってきたり、また、保護者の方から情報が入ったり、それから周りの教員が漏れ聞いてそれを伝えてきたりということになりますが、まずこういったものがあったときには、校長、副校長から本人に対して指導もありますし、また教員全体にも指導していっているところです。どちらにしても、暴言であったり、不適切な指導であったり、こういったことは絶対に認められないのだということを学校全体でしっかり理解した上で、教員一人ひとりが自覚してそういったことを行わないようにしていくことが重要だと思いますので、引き続き、教育委員会といたしましても指導を徹底していきたいと思っております。"},{"i":59,"speaker":"浅野委員","text":"よろしくお願いします。"},{"i":60,"speaker":"鈴木（博）委員","text":"これ、かねがね思っているのですが、小さい子どものしつけとか教育などでいろいろお話ししたりする機会が多いので思っているのですけれども、これ、例えば２ページ目の(2)の暴言、バスケットボールでできなかった子どもに「脳みそ空っぽか？ チビ。バカ」と大きな声で叫ぶ。誰が考えてもこれはよくないし、子どもの心に傷をつけると思うのです。これは誰が考えても体罰と同程度の暴言だと思うのです。\nただ、その上に出ている不適切な指導というので、避難訓練中に生徒が、天井から吊り下げられたガラス製の防煙壁をふざけてたたいたので、危険を感じて同生徒の体を押さえようとしてもみあったときに、同生徒の尻を右膝で先生は４回当たってしまった。これがもしも不適切な指導だとすると、こういうシチュエーションのときに、では、教師はどのような行動をとったらよろしいのでしょうか。\n東京都教育委員会ということで、直接品川区ではないかもしれないのですけれども、このシチュエーションが不適切な例として挙がっているということは、当然これは間違ったことをやったということだから、では、正しいことは対で当然あるはずなので、では、先生はどういう正しい態度をとったらよかったのか、僕はいくら考えてもわからないので教えてほしいのです。"},{"i":61,"speaker":"熊谷指導課長","text":"これは周りの子どもにけがをさせないようにということで、おろそうとしたということはあるのですが、そのときに故意に右膝で蹴っているということがあります。周りの子どもたちがその状況を見ていて、これは体罰だということで騒いだということもあるのですけれども、おろすだけではなくて、あえて４回蹴ったということがありますので、そこのところが不適切だった……。\n〔「では、故意に足をヒットした、４回やったというのが不適切な指導に当たる」と呼ぶ者あり〕\n〔「ただおろした、危ないのでおろした」と呼ぶ者あり〕"},{"i":62,"speaker":"塚本委員長","text":"答弁はそこで１回切ってよろしいですか。鈴木博委員。"},{"i":63,"speaker":"鈴木（博）委員","text":"はい。わかりました。別のことをお聞きします。\nこれ、分類例の不適切な指導に、「おでこを弾く（デコピン）」とあるのですけれども、これは要するに、額をピッとたたくことですね。それは不適切な指導になるのですか。"},{"i":64,"speaker":"熊谷指導課長","text":"どこまでがという具体的な部分はなかなか難しい部分もあるのですけれども、ただ、やはりこれは体罰ではないにしても、たたいたりですとか、それからおでこを弾いたり、いわゆるデコピンというのは不適切な指導であるというふうに分類上は記されております。"},{"i":65,"speaker":"鈴木（博）委員","text":"最後なのでもう１つお聞きしたいのですけれども、この指導の範囲内で、「寝ている生徒の肩を叩いて起こす」と書いてあるのですけれども、これは、行き過ぎた指導かどうかの分類の指導の範囲内に入ることなのでしょうか。"},{"i":66,"speaker":"熊谷指導課長","text":"これは授業中に寝ている生徒の肩を起きなさいということでたたいていますので、これは指導の範囲ということで。"},{"i":67,"speaker":"鈴木（博）委員","text":"当たり前です。"},{"i":68,"speaker":"熊谷指導課長","text":"ですので、当たり前ということで、それは当然やっても指導の範疇に入っているということで分類されてございます。"},{"i":69,"speaker":"鈴木（博）委員","text":"要するに、何が言いたいかというと、こういう報告の事例は、ただこうやって箇条書きにしても意味はないのではないかと思うのです。１つ１つの事例で必ず原因とか結果があるので、先生方もみんな別に生徒をいじめようと思ったり、体罰をしようと思ったりして対応する人などいないと思うのです。それがこういうシチュエーションになったということは、必ずそこに何らかのいろいろな状況があったはずで、例えば私など、今、小学生なども指導していますけれども、小学生でも大きい子だと身長が１６０cmぐらいで体重５０kgの子はざらにいるのです。そういう子どもに対するときに、おまけに生意気な子も結構いますから、だから、いろいろなシチュエーションがあると思うので、もちろん行き過ぎは、要するに、生徒の心を踏みにじって上から押さえつけようとして、何ら生徒にプラスになるということを考えないで感情的に対応するのはよくないと思うのです。ただ、やはりある程度、この子のためにこういうことをやりたいと先生が考えて行動する行動は、多少の強制力を伴うこともあるのではないかと思うのですけれども、そういうことも全て否定されるのでしょうか。"},{"i":70,"speaker":"熊谷指導課長","text":"さまざまな状況があると思いますし、また、安全面を配慮してというようなこともあろうかと思うのですけれども、一概にこうだからこの分類ということではなくて、ここに分類例というふうにあるのですけれども、この分類例に基づいて報告を上げますけれども、実際にはその前に、実際はどういう状況だったのかということについても面談等で確認をしていきます。そういった中で、こういった事例に当てはまるかどうかということを確認していくと同時に、また、実際にどういう状況であったかも全て含めて報告をしているところでございますので、例として分類は出されてはいますけれども、一概に手をはたくことイコール不適切な指導になるというようなことではございませんので、あくまでも例として示されているというふうにお伝えしていきたいと思います。"},{"i":71,"speaker":"鈴木（博）委員","text":"最後に１つお聞きしたいのですけれども、例えば今、言うことをきかないような行動をとる小学生が随分いますけれども、例えば教師が指導したときに生徒がそれに従わなかったらどうしたらいい。納得するまでお話し合いをしたらいいのですか。"},{"i":72,"speaker":"熊谷指導課長","text":"さまざまなお子さんがいますので、そのときの状況によってというのはありますけれども、どちらにしても、基本的には言葉で説明を、指導をしていくというのが原則であります。どちらにしても、やはり体罰という形でやることは絶対に認められないことでございますので、やはり子どもにはきちんと言葉で説明し指導していくということが重要であるというふうに考えております。"},{"i":73,"speaker":"鈴木（博）委員","text":"東京都医師会で「いじめについて」という講演会があって、そのときに筑波大学の附属小学校の先生が来て、自分のクラスのいじめの体験と、どのように対応したかというお話をしたのですけれども、そのときに、教師は絶対に体罰はだめだということと、子どもに対して、僕は君に対して深い愛情を持って君のためにやっているのだというその信念があれば、子どもは言うことをきくというようなお話をされたのです。僕はやはりそうだと思うのです。だから、いじめにしろ、教育にしろ、あるいは教師の体罰だと言われている事件にしろ、やはり子どものことを考えているか、生徒のために考えているかどうかということが一番大事だから、その辺の過去をしっかり踏まえた上でいろいろな対策を考えていただきたいと思うのですが、これは僕の要望です。"},{"i":74,"speaker":"飯沼委員","text":"まず、調査方法のところなのですけれども、教職員には校長による聞き取り調査、児童・生徒には質問の用紙で聞き取りということなのですが、具体的にどんな中身なのか、もし用紙があったら用紙も見せていただけたらと思うのが１点です。\nあと、報告数のところなのですけれども、上がってきている案件に対して、体罰をした側と言ったら……。中身的に体罰と決めつけられない微妙なところがあるのですけれども、加害の部分と被害の部分と分けた場合に、数では一致しないと思うのですが、この件はやはり体罰とかいじめの範疇に入るのではないかと思っている側のところと、受けた側のところが一致をしているのかどうか伺いたい。\nなぜかというと、その辺で理解の違いで不信感というか、やはり子どもも職員も保護者も信頼関係にのっとった教育を高めるという意味で、その辺がどうなっているのかということを伺いたいのが２点目です。\nあと、とにかく教職員の意識を高めていくということは、とても大事な、いろいろな場面で高めていただきたいのですが、この調査の後において、教職員でその結果を、校長先生が聞いたり、数をまとめたりはするけれども、学校自体で自分のところの状況が交流し合えているのかどうか。共有できているのか。ただ数的に報告をして取りまとめているのか、自分の学校の状況が現場で把握できているのか、そういうことをやっているのかどうかを教えてください。"},{"i":75,"speaker":"熊谷指導課長","text":"先ほど、調査用紙があるのかということですけれども、実際にこういった事案が上がってきたときには、都の調査用紙がございますので、それに基づいて配布をしております。\nそれから２点目ですけれども、子どもと教員が、例えばすり合わせというのでしょうか、できているかどうかということだと思いますけれども、これについてもこういった事案が上がってきたときに、両方から必ず確認をして、きちんとすり合わせをしております。\nそれから、本人同士だけではなくて、周りにいた子どもたち、それから教員、そういった周辺情報も必ず確認するようにしております。\nそれから３点目が、中で情報共有ができているかということですけれども、もちろんこういった事案につきましては、校内で二度とそういったことが起こらないようにということで、情報共有していると同時に、校長連絡会ですとか副校長連絡会でも同じような事案が発生しないようにということで周知徹底しているところでございます。"},{"i":76,"speaker":"飯沼委員","text":"ありがとうございます。\nすり合わせがされているということなのですが、そういった面で、例えば不具合が生じているというか、うまく信頼関係ができていなくて問題になったようなことはないのかどうか、その１点だけ。"},{"i":77,"speaker":"熊谷指導課長","text":"現段階では、そういった事案については発生してございません。"},{"i":78,"speaker":"飯沼委員","text":"ありがとうございます。"},{"i":79,"speaker":"大倉委員","text":"今の申告者別報告数で、すり合わせもお互いに認識しているということは確認したのですが、教員本人の方が５１件あって、学校別、これが児童・生徒本人と同じ認識がある件数はあるのですか。これはいろいろな各小学校、中学校で違うと思うのですが、例えば先生が、自分がやってしまったこれが体罰だったかとか、こういうことを子どもにしてしまったというのと、その本人からも先生にこういうことをされましたという件数がわりと同じものが多いのか、それとも全く別で、１１件と１３件は全く違う事案なのかということがわかると、もう少し先生と生徒の認識の差がわかるのかと思ったので、ここを１点聞かせてください。\nあと、体罰の数がここ数年減ってきてゼロになってきているというところで、校長先生等にアンガーマネジメントのようなことをしている、「叱る場面では、深呼吸６秒待って落ち着いて対応する」と取組事例のところに書いてありますが、その辺の効果がどのくらいあって、どういうふうに先生方にきちんと伝わって体罰の減少に関連しているのか、その辺はどのように考えているかを教えてください。"},{"i":80,"speaker":"熊谷指導課長","text":"教員本人と児童・生徒本人からの事例ですけれども、まず、どちらが先に言ってきたかということはございますけれども、基本的にはほぼ同じ内容について、教員と子どもたちとすり合わせというか、確認がとれているところでございます。ですので、同じ案件について同じような意識を持っているということがほとんどでございます。\nあとは、アンガーマネジメントにつきましては、やはりこれは今徹底して行っているところですので、まず深呼吸するですとか、そういったカッとなりやすい方たちには、自分自身でそういった傾向があるということで、自身を抑えるというような、そういったトレーニング等も含めて行っているところであります。\nですので、今回非常に減ってきたというのは、そういったこれまでの研修等の効果ですとか、また、さまざまなこうした服務事故等の事例を毎月のように学校の中でも周知徹底しているところでございますので、そういった中で抑えられるような教員が増えてきているというふうに思っています。ただ、これからも引き続き丁寧に指導していきたいと思っています。"},{"i":81,"speaker":"大倉委員","text":"ありがとうございます。\n申告者別報告数ではある程度合っているということで、あと若干気になっているのは、例えば大体同じ件数であるとするならば、１９件と２８件のこの辺の差はどういうところなのかと思っているのですが、その辺を教えてください。\nあとは、こういった怒りのコントロールについては、体罰については減っているけれども、不適切な行為というところでは若干増えているというようなお話だったかと思うのですが、その辺もぜひ減らせるように、より一層工夫して取組みを強めていっていただければと思います。"},{"i":82,"speaker":"塚本委員長","text":"今の数の違いについてはご質問ということですね。"},{"i":83,"speaker":"大倉委員","text":"はい。"},{"i":84,"speaker":"熊谷指導課長","text":"こちらは、申告者別の報告数でございますので、最初に申告がまずあったのはどちらからかということで、同時の場合もありますし、それから子どもが先にというふうに、そこから調べていって、やはりこれはということですり合わせができる場合もありますので、数の差が出ているところでございます。"},{"i":85,"speaker":"伊藤副委員長","text":"気になったことが、指導課の配付資料の中で、久々に「施設一体型一貫校」という表現になっているのです。「義務教育学校」に統一されているのではないかと思ったのですけれども、あえてそういう書き方なのかが１点と、それから、まとめて聞きますけれども、今のアンガーマネジメントは非常にすばらしいことだと聞いているのです。おそらく現場の教師が、課長も経験がおありでしょうけれども、子どもがいて、生徒になって、皆さんも人間だから、いろいろな感情が沸き起こるのは当然なわけであります。だけれども、それをマネジメントのコースを通して自分をしっかり抑えていくという、それをすることによって、こういうような下がっていることが目に見えているわけなので、改めてアンガーマネジメントの研修の具体的な展開と、これからの教員に対する指導の意識をお聞かせください。お願いします。"},{"i":86,"speaker":"熊谷指導課長","text":"こちらの調査なのですが、平成２７年度、昨年度の調査でございますので、「施設一体型」という書き方をしております。\n研修につきましては、センター長からお伝えします。"},{"i":87,"speaker":"村尾教育総合支援センター長","text":"このアンガーマネジメントの研修については、昨年度も実施をしており、今年度も校長連絡会を通し、また、特に各学校の主幹教諭、また生活指導主任等も広く情報を流しながら、各学校で必ず先生方、校内での打ち合わせ会またはそれぞれの生活指導の夕会等で広めていこうというふうに考えているところです。"},{"i":88,"speaker":"伊藤副委員長","text":"要は要望なのですけれども、繰り返し、各委員からもお話があったように、いろいろなケースがあって、教員もやはり人間ですから、時と場合によっては、それはいろいろな感情をお持ちになります。だけれども、それをどういうふうに展開するかによって変わってくるわけであるから、アンガーマネジメントの教育はすばらしいと思っていますので、できれば全ての教員に共有していただくように体制を強化してください。お願いします。"},{"i":89,"speaker":"塚本委員長","text":"ほかにご発言ございませんか。\n〔「なし」と呼ぶ者あり〕"},{"i":90,"speaker":"塚本委員長","text":"ご発言がないようですので、以上で本件を終了いたします。\n────────────────────────────────────────────\n(3) 平成２９年度品川区立学校教育職員採用候補者選考日程について"},{"i":91,"speaker":"塚本委員長","text":"次に、(3)平成２９年度品川区立学校教育職員採用候補者選考日程についてを議題に供します。\n本件につきまして、理事者よりご説明願います。"},{"i":92,"speaker":"熊谷指導課長","text":"平成２９年度品川区立学校教育職員採用候補者選考日程についての資料をご覧ください。\n１番、採用予定人数でございますが、６名程度を考えてございます。\n２番、資格要件でございますが、(1)または(2)のいずれかに該当する者ということで、(1)小学校教諭普通免許状および中学校教諭普通免許状、教科につきましては下に書いてあるとおりでございます。この両方を所持する者、もしくは、(2)でありますが、中学校教諭普通免許状（教科は下記参照）を所持する者で、品川区立学校教育職員として採用された後、３年以内に小学校教諭普通免許状を取得する意欲のある者としております。\n３番、選考区分でありますが、一般選考としては、年齢要件として、昭和６０年４月２日以降に出生した者。また経験者選考としましては、昭和４８年４月２日以降に出生した者ということで、下にありますように、国公私立の小・中学校または特別支援学校で、常勤の教員、継続して１２カ月以上の教員勤務実績がある者、また、非常勤の教員として週当たり３日以上、かつ１２時間以上の勤務条件で、通算２４月以上の勤務実績がある者としております。\n４番の選考日程でありますが、募集期間は来月６月１日水曜日から７月６日水曜日まで。第一次選考は７月３１日日曜日。結果発表としては８月中旬を考えております。第二次選考としましては８月２７日土曜日。発表は３１日水曜日。その後、採用面接は９月中旬。結果発表は９月下旬を考えてございます。"},{"i":93,"speaker":"塚本委員長","text":"説明が終わりました。\n本件に関しまして、ご質疑等ございましたら、ご発言をお願いします。"},{"i":94,"speaker":"飯沼委員","text":"選考の日程のところで、昨年の応募状況と採用人数を教えてください。\nあと、今回の採用予定人数６名程度というところの根拠も聞かせていただきたいのが２点目です。\nあと、資格要件のところなのですが、小学校免許と中学校の免許の両方を所持する者、なかなか大変だと思うのですが、現状において何％、この両方を持たれている先生がいらっしゃるのか教えてください。"},{"i":95,"speaker":"熊谷指導課長","text":"昨年度は、第二次選考を合格した方が１０名おりました。そこで面接を行いまして、採用内定者２名ということになっております。しかし、２名につきましては、併願先が１名は東京都、１名は川崎市ということで、最終合格をしたことで１０月末に採用辞退ということで、昨年度の採用はゼロ名ということになっております。\nそれから、１９名の固有教員がおりますけれども、小学校教諭の普通免許状所持者は１２名おります。中学校教諭の普通免許状所持者は７名、両方持っている者は１１名でございます。\n６名の根拠でありますけれども、まだ全ての学校に、そもそも予定している固有教員を満たしておりませんので、６名ということで、今年度は、昨年度採用できなかった人数も含めて６名程度を考えてございます。"},{"i":96,"speaker":"伊藤副委員長","text":"ちょっと大きな話なのですけれども、これは平成２１年度から採用して、現在、平成２７年４月１日現在で２０名となっているので、これはこれでいいのですけれども、教育委員会としてこの人材をどういうふうに、これから何名まで増やしていくのか。\nそれから、まさか全ての教職員を区固有にしようと思わないので、中長期的な中で、採用人数が何名で、こういう形で将来はこういうふうにして区固有職員と都費の職員のバランスをとっていくなり、大きな構想がまずあってほしいと思うのですけれども、それはあるのでしょうかという確認と、それから、目指す目標をもう一度教えてください。お願いします。"},{"i":97,"speaker":"熊谷指導課長","text":"中長期的な目標につきましては、今の段階でお答えできないのですけれども、ただ、やはり品川区立学校の固有の教員ということで、まずは品川区のことを一番知っている、そして子どもたちが卒業してもずっと相談できる先生ということで、固有の教員を採用していきたいと思っております。\nまた、実際に現在いる教員につきましても、区独自の市民科、英語科等につきましても、区の教育要領に基づいて実際に指導を行っていきますので、区の固有の教員ということで、品川区の一番わかっている、しかも異動のない先生ということで、目標を３０名、将来的には設定しているところでございます。"},{"i":98,"speaker":"伊藤副委員長","text":"結構大きな話なので、これは簡単にできる話ではないのだけれども、３０名は１つの目標。だけれども、私自身が感じる思いなのだけれども、固有職員の方はいいです、私たちも言ってきたから。だけれども、それをどういうふうに活用していくことの説明もいい、だけれども、今後その３０名をどうこれから育てていくか、より具体的な品川区の教育を受けて展開して、どういうふうに使っていくかということについての次のステップについて、そろそろ教育委員会で具体的に検討して、例えば５年後、１０年後のプランをつくって具体的な計画を考えるべきだと思うのですが、お考えだけお聞かせください。"},{"i":99,"speaker":"熊谷指導課長","text":"平成２１年度から区の固有教員を採用してまいりましたけれども、やはりそこから８年目ということになりますので、将来的な部分についても検討していく必要があるかと思います。また、区の中核となっていく教員ですけれども、今後、固有教員のキャリアプランというようなこともありますので、管理職の選考ですとか、そういったことも含めて検討していきたいと思っております。"},{"i":100,"speaker":"高橋（し）委員","text":"資格要件のところで、免許のお話で、(2)が、私の記憶だと去年はなかったかと思います。もともと小学校と中学校と両方の免許を持っているということは、どちらの学校も指導できるという点のみならず、小学校の教員になったとしても中学校の免許を持っているということは、そういうこともわかっているということで、指導上、大変有効。その逆もだと思っているので、両方持っていらっしゃる先生方が多くなるということは、多くの点で有意義だと思っているので、この方針はすごくいいと思います。\n(2)を加えた理由と、具体的に３年以内にというふうな手立ては、どのようなことを、先生がどう取るかという意味でのことと、それを教育委員会としてどうバックアップするか、持ち時間とか、いろいろなところが出てくると思うのです。その辺について、仮定の話になってしまうのですが、具体的にお考えというか、予定があればお話しください。"},{"i":101,"speaker":"熊谷指導課長","text":"現在、固有教員の中でも小学校免許を持っていますが、中学校の教員の免許を取ろうとして大学で勉強している者もいます。ただし、なかなか、中学校の免許を取ろうとしている中で、単位ですとか、そういったところで非常に時間がかかるというところがあります。ですので、今回、中学校教員免許状ということで、上級学校の免許を持っているということで、小学校の前期課程でも専門の科目を指導することができますので、そういったことで中学校の教員免許を持っていて、将来的に通信教育等で３年ぐらいかけて小学校免許を取れる者ということを考えているところであります。\nバックアップ体制というところですけれども、教育委員会でも固有教員の研修を行っているところですが、例えば、授業時数のことですとか、そういったことも加味しながら、通信教育等で単位が取れるように配慮していきながら、バックアップ体制を組んでいきたいと思っているところでございます。"},{"i":102,"speaker":"高橋（し）委員","text":"両免許を取るのはなかなか国公立の小学校課程でないと、あるいはその逆ではないと取りにくいところがあるので、そうではないところの先生が両免許、もう１つ取ろうということに関して、こういう機会を教育委員会のほうでつくっていただくのは大変ありがたいので、先ほどの持ち時間を含め、ぜひバックアップといいますか、同じ職場の先生方のご協力も必要だと思うのですけれども、ぜひそういった理解を得ながら、少しでもそういう先生が免許を取れるように支援をしていただければというふうに思います。これは要望です。"},{"i":103,"speaker":"塚本委員長","text":"ほかにご発言ございますか。\n〔「なし」と呼ぶ者あり〕"},{"i":104,"speaker":"塚本委員長","text":"ほかにご発言がないようですので、以上で本件を終了いたします。\n────────────────────────────────────────────\n(4) 適応指導教室マイスクール五反田の開設について"},{"i":105,"speaker":"塚本委員長","text":"次に、(4)適応指導教室マイスクール五反田の開設についてを議題に供します。\n本件につきまして、理事者よりご説明願います。"},{"i":106,"speaker":"村尾教育総合支援センター長","text":"それでは、私から、マイスクール五反田の開設についての説明をさせていただきます。資料、２枚目のほうのＡ３のものをご覧いただきながら説明をお聞きいただければわかりやすいかと思っております。\nまず、左上の四角、開設の背景でございます。文部科学省は、不登校問題に対する見解として、潜在的な不登校の６年生児童が中学校での生活等の違いにより顕在化した結果、中学校での新規の不登校が急増しているという部分、また、不登校のきっかけが、学業不振や進路にかかわる不安、入学・転編入学・進級時の不適応の理由なども増加しているというふうに指摘しており、同様の傾向が本区でも見られております。\nそこで、学校での集団生活や学習になじめない生徒が、一時、学校を離れて学習できる居場所を確保し、学習したり、悩みや不安を相談したりできる、１つ落ち着ける居場所をつくることで、不登校の未然防止、また初期対応を図り、学校・学級への復帰を目指すことを目的として、このマイスクール五反田を今年の６月からスタートしたいと考えております。今は、その開設に向けてさまざまな準備をしているところでございます。\n次に、入室までの流れと主な支援内容についてです。下のほうの大きな枠をご覧ください。\nまず、概要という部分でございます。体験通室ということで、対象は、区内中学校または義務教育学校（後期課程）に在籍するいわゆる７年生から９年生の生徒で、保健室登校や登校しぶり、欠席しがちであったり、遅刻が多い等、学校や集団への不適応の初期状態が見られ、登校や学習意欲は見られる、自学自習できる生徒を対象と考えています。\n開設については、水曜日以外の午前９時から正午まで、子どもたちは週１日、曜日固定になりますけれども、期間は最長で１カ月以内ということで体験をしてまいります。その間に子どものそれぞれの個々の学力状況であったり、態度とか状況、在籍校の担任などからの聞き取り、本人や保護者等の面接等を通して生徒個々の状況確認をし、個別の支援方法の検討をした上で、判断会議、そして正式な入室というふうに考えているところでございます。\n入室決定後につきましては、期間は体験を含めて６カ月間と考えています。時間割については、右のほうのマイスクール五反田入室というところの時間割の表を見ていただければと思いますが、９時から１２時までということで、朝の会、そしてＴＩＭＥ1)、ＴＩＭＥ2)、ここでは個別の自習をしたり、この後説明しますけれども、メンタルフレンド等との悩み相談であったり、会話等を踏まえながら１日を過ごしていくというような流れになっております。通常５０分を２コマ学習時間として設けているところです。\n支援体制といたしましては、スタッフとして指導員を１名、それから、今センターにいます学校経営監２名による個別の支援がメーンになります。\n特徴といたしましては、その他、生徒と年齢の近い大学生をメンタルフレンドとして一、二名配置し、学習の補助やさまざまな相談を受けていくということでございます。\nまた、必要に応じてメンタルフレンドが学校に出向き、保健室登校であれば、保健室で一緒にともに生活をしたり、また、家庭への訪問型の支援、アウトソーシングみたいなものも少し考えているところでございます。\nそして、教育総合支援センターのカウンセラーによる定期的なアセスメントやカウンセリング、ソーシャルスキルトレーニングなども効果的に取り入れていこうというふうに考えているところです。\n場所ですが、五反田にある教育総合支援センターの研修室がございます。午前中はある程度、研修等が入っていませんので、うまくこの時間を活用し、この研修室で行います。\n下の机の図を見ていただければと思います。教室を自由に使えますので、机と椅子を使いながら、朝の会では全員でミーティング、また、時間になると個別であったり、グループであったりという、いろいろな形をとりながら考えているところでございます。\n子どもたちは個々によって状態が違いますので、柔軟に対応していくとともに、必要に応じてマイスクール八潮をはじめ関係機関との連携も当然図っていく。いずれにしても、目的につきましては、学校や学級への復帰ということになりますので進めていく。ただし、学校または学級へ復帰しましても、個々においては継続的な支援を続けていこうというふうに考えているところでございます。\n最後に、この表の右の上のほうをご覧ください。マイスクール八潮とマイスクール五反田の違いを簡単に説明いたします。\n五反田については、繰り返しになりますが、対象は７年生以上で、このように不適応の初期状態を起こしている子どもたちが対象になります。それに対してマイスクール八潮は、どちらかというと、長期欠席をしている子どもたちが対象になってくるということでございます。\n内容については、マイスクール五反田は、どちらかというと個別での子どもたちへの対応に対して、マイスクール八潮では、できれば集団で、体育とか音楽とかを現在も行っておりますけれども、コミュニケーションをメーンにしていますので、集団での活動が主になってくるというふうに考えています。\n週１日、２日が五反田に対して、マイスクール八潮は、週５日、どの日に来ても構わないということになっています。\n人数は、マイスクール五反田では１日１０名程度を許容できます。マイスクール八潮は定員が３０名です。マイスクール八潮は、通常、定員が３０人なのですが、１５名から２０名ぐらいが大体毎日来ている数かと思っております。\nいずれにしても、マイスクール五反田については、学校とマイスクール五反田という２つ併用型の体系をとっていくというような考え方、つまり、補助的機能というような考え方で行っていきます。マイスクール八潮は、完全に学校にはまだ行けないという子どもたちですので、学校に行ったり、マイスクール八潮に行ったりということはあまりできませんので、マイスクール八潮単独での生活改善や対人関係づくりということを進めていく、このような形で考えております。\nなお、この６月のスタートにあたり、実際にまだ開設していませんので、やりながら、子どもたちの状況、また、さまざま協議を含めながら、子どもたちにとってよりよい学校への復帰システムとして実践的な研究も進めていこうというふうに考えているところでございます。"},{"i":107,"speaker":"塚本委員長","text":"説明が終わりました。\n本件に関しまして、ご質疑等がございましたら、ご発言をお願いします。"},{"i":108,"speaker":"飯沼委員","text":"なかなか学校に行かれない不登校のお子さんたちの居場所が増えることはとてもうれしいと思っていたのですが、私、勝手に今度のマイスクール五反田もマイスクール八潮と似たような状況が、２つ目ができるのかと受けとめていたので、２枚目の右の違いを見ました。違いはわかりました。中学生のところが増えているということなのですけれども、私は目黒区の境目のところからここに通ってくるので、八潮は遠いという思いがしています。３年生から６年生の子どもたちの居場所は、マイスクール八潮で足りているのでしょうか。私はもう少し近いところにもつくってほしいと思います。その辺の需要について１点お伺いをしたいと思ったところと、体験を含め６カ月以内というこの辺のめどは、どの辺から来ているのかということを１点お聞かせいただきたいのと、あと、指導員のところなのですが、教育相談員と学校経営監という、この方たちの身分というか、資格を教えてください。"},{"i":109,"speaker":"村尾教育総合支援センター長","text":"まず、八潮との比較になります。ご案内のとおり、マイスクール八潮は、ここに書いてあるように、学習室もあり、音楽室、校庭、体育館ということで、集団的な活動ができるのに対して、どうしてもスペース的に五反田のほうはできないというような施設の問題点がございます。マイスクール八潮の３年生から６年生までの今の状況ということでございますが、やはり現実問題、八潮のほうも７年生以上の子どもたちが多くなっているということが現状でございます。\n２点目、６カ月という期間なのですが、これは国のさまざまな不登校に対する調査をされている方が、やはり期間をある程度決めた状態で、とにかく学校復帰が第一目標になりますので、６カ月が１つの目安として考えていくのがいいことではないかということで、一応、６カ月というふうな期間を決めましたけれども、絶対６カ月になったら全員出すというわけではなく、目安として６カ月というふうに現在は設定しているところです。\n３点目、指導員につきましては、非常勤講師という形で、月１６日配置ということで進めています。学校経営監も同じく非常勤という扱いで、センターのほうで勤務をしていただいているところです。"},{"i":110,"speaker":"飯沼委員","text":"中学生、７年生以上のところが多くなっているというところにおいては、新しい試みのマイスクール五反田であるというところにおいては期待をしたいと思っております。\nが、ぜひ小学校の不登校のところ、数が実際増えているかどうかもわからないのですが、結構小学校のところでも悩んでいるお子さんの話も聞くので、その辺の対応もぜひ力を入れていただきたいと思っています。\nあと、マイスクール八潮とか五反田以外で、民間とかＮＰＯとかをかりての不登校のお子さんの対策にもぜひそういったところの意見も聞きつつ拡大できて、居場所が増えたらいいと思っているので、その辺のお考えがあったらお聞かせください。"},{"i":111,"speaker":"村尾教育総合支援センター長","text":"１点目の小学生においてもというところでございます。これについては、改めて各学校、特に小学校の段階で学校の集団とか学習に対する不適応を起こす子どももやはりいらっしゃいますので、改めて小学校または義務教育学校の前期課程においては、都のスクールカウンセラー、巡回相談等をうまく活用しながら、子どもたちの様子を確認をしていこうというふうに考えています。\n１つの案といたしましては、本年度から特別支援教室を各小学校に設置をしておりますので、例えばそこが１つの居場所として使えないかどうかとか、いろいろな方法を現在模索をしながら進めていこうというふうに考えているところでございます。\n２点目につきましては、今、国のほうでフリースクールを含めてさまざまな検討がされていて、すぐにはまだ法案は通っていないのですが、その辺の国の動きも十分見ながら、やはり今後、子どもたちの学習の場面であったり、生活の場面の複線化みたいなものも進んでいくのかと思いますので、その辺については十分注視しながらこちらのほうで検討材料に入れていこうかと考えてございます。"},{"i":112,"speaker":"飯沼委員","text":"後段のところ、ぜひ区内でいろいろ不登校問題、子どもたちのことを取り上げて頑張っているところもあるので、ぜひお話を聞く機会を持ちながら検討を拡大していただきたいと思います。よろしくお願いいたします。"},{"i":113,"speaker":"高橋（し）委員","text":"体制のことなのですけれども、マイスクール五反田室長ではないですけれども、そこの責任というか、まとめ役みたいな方は、五反田のほうにいらっしゃる指導主事の方なのか、それとも指導員、学校経営監の方なのかということなのですが、なぜかというと、延べにすると結構な生徒が来ることになるので、何とか君は何とか中学校と連絡をとれているとかという、そういう把握、おそらく個人カードみたいなものをつくっていくのではないかと思うのですが、その辺の言うなれば、校長先生ではないですけれども、１つの集合体なわけなので、全体を把握できて、いろいろなそういうことをまとめる方がいらっしゃるのか、どういう体制でやられるのか、そこのところ、２つの指導員と学校経営監が非常勤の方ということなので、またちょっと立場が違うと思うので、そのあたりをお尋ねします。"},{"i":114,"speaker":"村尾教育総合支援センター長","text":"このマイスクール五反田においては、現在のところ、主任指導員ということで、一番最初に書かせていただいた指導員をある意味中心として、マイスクール五反田の運用を考えているところです。この指導員がさまざま打ち合わせの中で、個別にメンタルフレンドとの連携を図ったり、個々の状況把握、また学校との連携等、ある意味、ここが中心に仕切っていく、そういうような体制で進めていこうと考えています。"},{"i":115,"speaker":"高橋（し）委員","text":"そうなると、教員免許所持者という形であるのですが、ただ、もちろん教員経験の方、１０人以上の中学生を全体を把握していくというところに関しての運営のところがちょっと不安な点があるのですけれども、その点はどういうふうに進めていかれるのでしょうか。"},{"i":116,"speaker":"村尾教育総合支援センター長","text":"委員おっしゃるとおり、１日一番多くて１０名がずっと１週間なので、簡単に言うと５０名の子どもが１週間というふうにマックスになる可能性は多くあります。その中で指導員の方を学校経営監のお二人が支えながらという言い方はあれなのですけれども、個別にそれぞれ担当を決めて進めていく。またこれに指導主事も不登校対策ということで担当がセンターにもともとありますので、その辺も踏まえながら、どのような体制をするのが一番うまく回るか、これもスタートしてからよく考えながらいこうと思っています。\nただ、当然、個人情報等の確保もありますし、学校との連携の仕方が複雑になってきますので、十分検討させていただければと思っております。"},{"i":117,"speaker":"高橋（し）委員","text":"ありがとうございます。\n在籍校と連携をしていくという点も、今お話があったように、かなり細かいところまでやらなければいけないと思うので、この開設は非常にいい試みだと思って大変期待をしているので、ぜひうまく回るように、子どもたちがまた学校に戻れるような形で進めていっていただければと思います。"},{"i":118,"speaker":"鈴木（博）委員","text":"今の高橋しんじ委員の続きなのですけれども、メンタルフレンドというのは、これはどういう資格で、どのような方を想定されているのでしょうか。"},{"i":119,"speaker":"村尾教育総合支援センター長","text":"簡単に言うと大学生なのですが、現在、外部委託という形で、子どもたち、学校の放課後とかに派遣をするような会社がありまして、そこと契約をして、教員志望であったり、ここに書かれている心理学等、子どもたちとかかわりができるような方々を推薦をして、この業者が配置していただくというような方法をとっております。最初は、大学生、希望して、または募集をしてとは思ったのですが、急に休んだりすると、その都度、対応ができないので、きちんとした対応ができるような形で外部委託というふうに考えています。\n１つのメリットといたしましては、生徒の興味関心があるものが、例えばの話なのですけれども、将棋が結構好きだというのであれば、将棋がわかる人を派遣してもらいたいとかということもできるということだったので、今後、メンタルフレンドの人たちは、信頼関係を結ぶのがやはり重要でありますので、そういうところでこのような形でメンタルフレンドの人たちを派遣するというような考えでございます。"},{"i":120,"speaker":"鈴木（博）委員","text":"ちょっと僕のイメージと違っていたのですけれども、教員志望や心理学専攻の大学生が来るのかと思ったのですけれども、何が心配かと思ったのは、教員だとか心理学だとか勉強中の学生が、不登校の子どもを変にいじくって、こういう子どもは、結構、いじくると悪くなってしまって、かえって悪化したりすることもあると思うので、そういう面で、例えばこういうメンタルフレンドというような方は、その方たちの行動を統括したり、総括したりするもう１つ上級のアドバイザーみたいな方は、人材派遣会社の方ということになるのか、それとも、ここの学校経営監だとか指導員になるのでしょうか。"},{"i":121,"speaker":"村尾教育総合支援センター長","text":"この派遣される業者は、事前にその会社で研修をしていただくことになっています。そのときに、不登校の子どもたちの現状であったり、またはかかわり方については、きちんとした研修を設けてもらう、そのうえで改めてセンターのほうに来ていただいて、子どもたちの扱いについては、学校経営監の先生方はもともと教員の経験者でございますので、こういうことは気をつけなければいけないということも踏まえながら進めていこうというふうに考えています。"},{"i":122,"speaker":"鈴木（博）委員","text":"では、スタッフが監督するというふうに理解してよろしいわけですか。学校経営監だとか、指導員みたいな、そこにいらっしゃる方がメンタルフレンドを統括しているというふうに考えてよろしいのでしょうか。"},{"i":123,"speaker":"村尾教育総合支援センター長","text":"はい、そのとおりでございます。指導員または学校経営監が育成をしていくということと、指導していくということになります。"},{"i":124,"speaker":"塚本委員長","text":"ほかにご発言ございますか。\n〔「なし」と呼ぶ者あり〕"},{"i":125,"speaker":"塚本委員長","text":"ほかにご発言がないようですので、以上で本件を終了いたします。\n会議の運営上、暫時休憩をいたします。\n○午後３時４８分休憩\n○午後３時５５分再開"},{"i":126,"speaker":"塚本委員長","text":"ただいまより、文教委員会を再開いたします。\n熊谷指導課長と村尾教育総合支援センター長は、公務のため途中退席されましたので、ご了承願います。\n────────────────────────────────────────────\n(5) すまいるスクール利用料の減免処理の遅れについて"},{"i":127,"speaker":"塚本委員長","text":"(5)すまいるスクール利用料の減免処理の遅れについてを議題に供します。\n本件につきまして、理事者よりご説明願います。"},{"i":128,"speaker":"高山子ども育成課長","text":"それでは、私から、すまいるスクール利用料の減免処理の遅れについて、ご報告申し上げます。資料はＡ４、１枚でございます。\n全児童放課後等対策事業であります「すまいるスクール」につきましては、本年４月からの事業の見直しの中で、利用料の改定と、利用料の減額・免除の仕組みにつきまして導入したところでございます。しかしながら、免除世帯の一部につきまして、４月の処理手続が遅れましたことをご報告ならびにお詫び申し上げます。大変申しわけございませんでした。\nまず概要から説明させていただきます。\n本年４月から、就労家庭の保護者からの要望等を受けまして、運営時間を延長するとともに、利用料の見直しと、新たに利用料の減免制度を導入いたしました。しかしながら、減免の申請をいただいた世帯のうち、区市町村税非課税世帯または均等割のみの家庭世帯のうちの１９７件について処理手続の遅れが生じ、４月の利用料を一旦規定の金額で口座から引き落とさせていただくこととなり、対象となる方々には大変ご迷惑をおかけすることとなりました。\n資料の項目１番をご覧ください。減免処理が遅れた理由でございます。\n事業見直しの過程の中で新規に電算システムを構築しまして、利用料の管理や利用料の収納管理の仕組みを開発いたしました。しかしながら、電算システムの構築に際しまして、減免判定をする上で必要な所得の状況を把握するための例えば生活保護情報でありますとか、住民税の情報等の他の部門が保有いたします情報を取得する必要がございまして、その仕組みづくりに時間を要してしまいました。また、減免の判定のシステム化にあたりましては、減免事由に税の非課税世帯等の要件に加えまして、寡婦のみなし適用後の非課税世帯または均等割のみ課税世帯を加えたことで、想定よりシステムの構築が複雑化し、開発に多くの時間を要することとなってしまいました。そのため、減免処理作業全般に遅れが生じ、４月の引き落としに際しましては、減免処理前の規定の金額で引き落としをさせていただくこととなりました。\nなお、今申し上げましたこれらの事由につきましては、いずれもシステムの開発が終了したことに伴いまして解消済みでございますので、今後、同様の遅れが生じることはございません。\n項目の２番をご覧ください。利用料の還付でございますが、一旦引き落としさせていただきました４月分の利用料につきましては、５月の下旬に対象となります世帯に今回のお詫びと利用料のお返しに関する丁寧なお知らせをご案内させていただき、速やかに振込みをさせていただく予定でおります。\n項目の３番、利用料をご覧ください。すまいるスクールの利用料は、利用する時間帯ごとに設定されておりまして、月額の利用料は、１７時までの利用が２５０円、１８時までの利用が３,２５０円、１９時までの利用が４,２５０円となっております。\nしたがいまして、今回の影響でございますが、引き落としに際しましては、最大の方で４,２５０円、最小の方ですと１,５００円の金額を一旦引き落としさせていただいております。今申しました１,５００円と申しますのは、１７時までの利用の方、２５０円につきましては、処理の効率等も考慮した上で、６カ月分を前納という形で２５０円掛ける６カ月分ということで１,５００円分を引き落としさせていただきます関係で、一番小さな額の方ですと１,５００円の金額を一旦引き落としをさせていただいております。\n最後に、項目の４番、利用料減免の概要でございます。こちらは、(1)減免事由としまして、減額の事由として１事由、免除の事由としまして４つの事由を設けてございます。\n(2)番としまして、減免申請の状況でございますが、先月、４月の文教委員会でご報告いたしました４月１日時点での登録者数８,７１６人のうち、減免申請をいただいた件数は２,５１３件で、全体の２８.８％となります。この方々のうちの１９７件、およそ７.８％の方々に大変ご迷惑をおかけいたしました。今後、こうしたことが二度と発生いたしませんよう、厳密なる進行管理に努めるとともに、ご迷惑をおかけいたしました方々に丁寧かつ速やかな返還手続をとらせていただきたいと考えております。\n説明は以上となります。このたびは誠に申しわけございませんでした。"},{"i":129,"speaker":"塚本委員長","text":"説明が終わりました。\n本件に関しまして、ご質疑等がございましたら、ご発言をお願いします。"},{"i":130,"speaker":"石田（ち）委員","text":"システム開発が終了したことで解消済みであるということで、５月下旬には関係のお知らせと、口座に返納を行うということなのですけれども、数字の関係なのですが、一番下の登録数８,７１６人のうち、この利用料、(1)、(2)、(3)、利用時間別、これの人数の内訳がわかれば教えていただきたいのと、次の減額と免除の方が全体で２,５１３件ということですけれども、これも減額、免除の内訳を教えていただきたいのと、あと、一番上のところに、遅れのところに４月分について、減免対象世帯というふうにあるのですけれども、そうすると、減額と免除の対象者のうち１９７件の処理の手続が遅れたということで理解していいのかということ、それぞれお願いします。"},{"i":131,"speaker":"高山子ども育成課長","text":"時間帯ごとと申しますと、現在、持ち合わせている数字としましては、２,５１３件の申請のうちの、いわゆる現状、減額の対象となります多子世帯につきましては１,６１１人ということで、率にしますと大体６４％ほどの方が全体の減免申請のうちの多子世帯に該当するといった件でございます。\nそれから、今持ち合わせている数字としまして、１９７件の今回のご迷惑をおかけいたしました方々のうちの１７時までの利用の方が１４４人、１８時までの利用の方が４２人、１９時までの時間帯が１１人ということで、これらの合計が１４４人、４２人、１１人と足しましたところ１９７人の方、こういった方々に影響を及ぼしてしまった、そのような内訳で把握しているところでございます。"},{"i":132,"speaker":"浅野委員","text":"減免処理が遅れたということで報告いただきました。たしか去年の９月の委員会だったと思いますけれども、スタート時にエラーが発生しないようによろしくお願いしますと質問をさせていただいたことを思い出したのですけれども、やはりこういうシステムの開発は非常に、後からわかることとか、追加になることとかあると思うので、二度とないとは思いますけれども、最後に迷惑を受けるのが区民の方ということになりますので、これからもよろしくお願いしたいと思います。\n申請状況で、登録数は８,７１６名となっていますが、そもそも区としての申込み数のイメージ、どのぐらいを想定されたのか、あと、減額・免除の申請件数についてもそうですけれども、差異といいましょうか、教えていただければと思います。"},{"i":133,"speaker":"高山子ども育成課長","text":"委員ご指摘の登録のほうの率の見込みかと思うのですが、先月の文教委員会で、前回の登録数ということで８,７１６人、これが率で申しますと６０.８％というご報告をさせていただきました。例年ですと、おおむね６２％ほどで４月はスタートしておりますので、全登録数につきましては、見込みといいますか、年度における誤差の範囲というふうに捉えております。\nまた、減免の申請の件数につきましては、やはりおおむね３割程度の方の申込みがあろうかという見込みを当初しておりましたので、今回、２８％ということですので、大体統計的な誤差の範囲というふうな幅と考えておるところでございます。"},{"i":134,"speaker":"浅野委員","text":"ありがとうございました。\n登録数、それと減免の数という形で伺いました。この数字については、多い少ないとか、いろいろ論議はあるかと思いますけれども、子どもたちがすまいるスクールを楽しみにされているということもありますので、これからも発展するように努めていただければと思います。よろしくお願いします。"},{"i":135,"speaker":"伊藤副委員長","text":"減免処理が遅れた理由の中で契約の関係でお伺いしたいのですけれども、原因が「想定よりシステム構築が複雑化し、開発に多くの時間を要した」こととすれば、原因は品川区側にあるということでいいのですね。そうすると、プログラム作成会社への追加の品川区の負担が生じたということがありますでしょうか。お聞かせください。"},{"i":136,"speaker":"高山子ども育成課長","text":"今回、開発業者を選定するにあたりましては、募集に基づきまして、競争入札で業者を決定させていただいております。仕様に基づく開発ですので、当初見込んでいた作業日よりも若干時間がかかったでありますとか、あるいは複雑化したということで、受託者側であります業者等にこの責任はないということが１つございます。\nですので、厳密なる進行管理と仕様の詳細な設定を速やかに行えていれば、このような事態にはならなかったということもありますので、この点１点、大変申しわけないということでお詫び申し上げます。\nそして、この件で結果的な負担という意味で言いますと、納期内の開発ということに関しましては、３月末日をもって納品されておりますので、品川区の追加の負担等は生じておりません。"},{"i":137,"speaker":"伊藤副委員長","text":"確認しますけれども、システム自体は３月に完成しました。だけれども、その中でこれが遅れたのですよね。ということは、当初、品川区の仕様からすれば、これも入ったものが３月にできる予定だった。だけれども、それが完成したけれども、これだけが遅れたということなのだから、そこにやはり品川区の製品があるわけだから、それはプログラムを変えたりしないとおかしいでしょう。その辺のもう少しわかる説明をお願いいたします。"},{"i":138,"speaker":"高山子ども育成課長","text":"ご説明が不親切で大変申しわけございませんでした。\n工程管理の面から生ずる遅れでございますので、期間がおおむね５カ月程度の中で開発が終わるような形で進捗管理をする中で、重要な部分、開発部分が開発期間後半にずれ込んだということがあって、結果として納品が３月末にあったわけなのですが、電算システムとしての完成が年度末になったということです。\nそして、それを受けましての４月の減免処理ということになりますので、システムの完成を受けましての４月の入力等の作業発生ということになりますので、そういった部分のその後に発生する作業等が全般的に遅れたという、その結果として４月の引き落としのデータを作成するその日にちに、この減免処理、一部の方については間に合わせることができなかった、そのような状況でございます。"},{"i":139,"speaker":"伊藤副委員長","text":"私の理解としては、そうすると、システム開発自体は間に合いました。それがたまたま年度末にあって、その後の事務処理部分で遅れたということなのですか。そうすると、それは品川区の責任になってくると思いませんか。だからこそ余計に関連しているのは、では、なぜ遅れてしまったのか。わかっていることでしょう。それに対して事務的な体制もとっているべきだと私たちは思っていたのだけれども、できなかったということでは、議会としてはちょっと厳しくやらなければいけないと思うのですが、いかがですか。"},{"i":140,"speaker":"高山子ども育成課長","text":"委員ご指摘のとおり、当然システム開発と並行して事務処理手続が早期に始められる、これを前提とした４月の引き落としの処理に間に合わせる、そのような当初の全体スケジュールで考えていたところでございます。しかしながら、減額・免除の処理がさまざまなご要望を受けて年末時期に確定したような、そういった状況もございまして、それをシステムに取り込むにあたっては、詳細を詰めた上で反映させる、そういったこともあった関係で、今般の不手際につながってしまった、そのような状況でございます。"},{"i":141,"speaker":"伊藤副委員長","text":"まとめますけれども、私は、皆さんの仕事はすばらしいものだと思っていますし、このことで批判するつもりもないのでございます。それはぜひご理解ください。\nただ、そういう目標年度があって、この話についてはシステム自体は完成していたとするならば、やはりその後の事業展開の中で起こった原因についてはぜひ確認をしていただいて、これからはこういうことがないように対応をよろしくお願いいたします。"},{"i":142,"speaker":"塚本委員長","text":"ほかにご発言ございますか。\n〔「なし」と呼ぶ者あり〕"},{"i":143,"speaker":"塚本委員長","text":"ご発言がないようですので、以上で本件を終了いたします。\n────────────────────────────────────────────\n(6) 平成２８年４月の入園状況について"},{"i":144,"speaker":"塚本委員長","text":"次に、(6)平成２８年４月の入園状況についてを議題に供します。\n本件につきまして、理事者よりご説明願います。"},{"i":145,"speaker":"竹田保育課長","text":"平成２８年４月、保育園の入園状況について、ご報告いたします。\nまず、入園の申込みですが、３,２８１人の方の入園申込みをいただき、審査をいたしました結果、２,３１０人の方の入園を決定したところでございます。\nこの入園決定を受けまして、平成２８年４月１日現在の認可保育園の在籍状況は、お手元にお配りしました資料、平成２８年４月の保育園別在籍状況のとおりでございます。表面が区立保育園、裏面が私立保育園となっており、公私立の合計は、裏面の表の最終行に記載してございます。\n３歳未満でございますが、公立・私立保育園の合計で、定員が３,２０６人となっております。これに対しまして、在籍児が３,５１０人、定員比が１０９.５％でございます。\nまた、３歳以上につきましては、定員が４,３９４人に対しまして、在籍が４,１７９人、定員比９５.１％となっております。\n全体の合計といたしましては、定員７,６００人に対しまして、在籍児７,６８９人という状況でございます。全体の定員比は１０１.２％となっております。\n待機児童対策に関しましては、待機児童対策担当課長がご説明いたします。"},{"i":146,"speaker":"大澤待機児童対策担当課長","text":"それでは、待機児童数のご報告をいたします。\n平成２８年４月１日現在の待機児童数は１７８人でございます。\n前年度と比較いたしますと、申込みは４８２人増加いたしましたが、待機児童は３７人の減少となりました。"},{"i":147,"speaker":"塚本委員長","text":"説明が終わりました。\n本件に関しまして、ご質疑等がございましたら、ご発言をお願いします。"},{"i":148,"speaker":"石田（ち）委員","text":"配っていただいた資料の裏面の一番下の表です。これの不承諾数と待機児童数のゼロ歳から５歳の内訳がわかれば伺いたいのですが。"},{"i":149,"speaker":"大澤待機児童対策担当課長","text":"待機児童の年齢別の内訳、まずそちらからご報告いたします。\n待機児童のうち、ゼロ歳が６５人、１歳が８０人、２歳が２７人、３歳が６人、四、五歳児はいらっしゃいません。\n不承諾の内訳です。不承諾のほうでございますが、ゼロ歳が２３１人、１歳が４０１人、２歳が２５２人、３歳が６５人、４歳が１４人、５歳が８人ということで、計９７１人となります。"},{"i":150,"speaker":"石田（ち）委員","text":"ありがとうございます。"},{"i":151,"speaker":"飯沼委員","text":"１ページ目の区立の保育園のところなのですけれども、３歳未満児のところの定員と在籍児数のところがありますけれども、３歳未満児の定員が１,９０２人になっているところの在籍の小計が２,１７２人になっているのです。２７０人定員よりも多いのですが、この中身が、定員拡大が行われているところもあると思うのですが、あと、弾力化もあるのかどうか。あるのだったら、それぞれどういう具合でここの定員以上、プラス２７０人になっているのか、ここを教えていただきたいのが１点です。\n２点目に、裏面の私立なのですけれども、本当に頑張って、平成２８年度は７園の保育園をつくっていただいたのですが、特に新しい私立の６園のところなのですが、３歳未満のところは埋まっていますけれども、なかなか四、五歳のところまで全部定員になっていないというところにおいて、頑張ってくださっていると思うのですが、経営上のところで大丈夫なのかと心配をしているのですが、だんだん子どもたちが年度が上がっていけばいっぱいにはなるわけですけれども、しばらく定員があいている状況、大きい子はなかなか入りにくいと思うのですが、その辺の経営的な問題はないのかどうか聞かせてください。"},{"i":152,"speaker":"竹田保育課長","text":"まず、区立の定員に対する在籍児数の件ですが、定員はそもそも少し抑えめに設定しておりまして、近年、面積の許す限りで弾力化をして拡大をしてきました関係で、トータルでこれだけの差ができているということでございます。定員は、この拡大に伴って増やしておりませんので、年々若干差が出ていくというところでございます。\nそれから裏面の私立のほうの経営のことでございますが、何社かにお話を聞いたところでございますが、年齢の高い児童が当初は埋まらないというのは、どこの園でも開園時に起こることですので、これは想定しているところですということでお話を聞いております。"},{"i":153,"speaker":"飯沼委員","text":"認可保育園なので、基準があるのでなかなか難しいとは思うのですが、埋まらない部分の年齢を置きかえて工夫をするということができないのかどうかが１点と、もう１つは、教えていただきたいけれども大変かと思っているのが、認可保育園に入園できた方の指数、点数と、階層別にどこの階層の方が入っているのかという一覧表をいただけたら、個々で伺うとわかるのですが、一覧表でどういう水準のところの人までが入れているのかという一覧表をいただきたいと、今の今、急に言ったので、委員長も頭が痛いと思うのですが、そういう資料を出していただけたらと思うのですが、いかがでしょうか。"},{"i":154,"speaker":"竹田保育課長","text":"まず、置きかえの問題でございますが、こちらはお子さんが年齢が上がるごとに埋まっていくということですので、今ここで埋めてしまうと、上がってきた方が在園できなくなるということがありますので、置きかえることは難しい状況でございます。\nそれから、入園できた方の指数ですが、個別にお答えさせていただいておりますので、一覧表というのも難しいかと考えております。"},{"i":155,"speaker":"飯沼委員","text":"後段のところなのですが、個別にお答えということは、個別とはどういうことなのか、議員としては求められないということなのか、そこの個別にお答えという中身を教えてください。"},{"i":156,"speaker":"竹田保育課長","text":"申し込みいただいた方からのお問い合わせの中で、可能な限りご説明の中でお話ししているという状況でございます。園によっては、年齢で１人しか入れないような園もございますので、そこで最低点を、指数を公表すると、その園のその方の指数がわかってしまうということもありますので、全ての公表は難しいというところでございます。"},{"i":157,"speaker":"飯沼委員","text":"ありがとうございます。\n個人情報というところもあるとすれば、園名を黒塗りにしていただいて、わかるほうも……。\n〔「順番がわかってしまう」と呼ぶ者あり〕"},{"i":158,"speaker":"飯沼委員","text":"順番、順番はわからないと思う。何か工夫をして出していただける方法はないでしょうか。お願いですがいかがでしょうか。"},{"i":159,"speaker":"竹田保育課長","text":"委員のご質問でございますが、お求めになられている内容等が今はっきり把握できませんので、別途ご相談させていただきたいと思います。"},{"i":160,"speaker":"飯沼委員","text":"はい、わかりました。ありがとうございます。"},{"i":161,"speaker":"塚本委員長","text":"ほかにご発言はございますか。\n〔「なし」と呼ぶ者あり〕"},{"i":162,"speaker":"塚本委員長","text":"では、ほかにご発言がないようですので、以上で報告事項を終了いたします。\n────────────────────────────────────────────\n３ その他"},{"i":163,"speaker":"塚本委員長","text":"次に、予定表３、その他で何かございますか。"},{"i":164,"speaker":"竹田保育課長","text":"お手元にお配りいたしました宮本慎也さん、元プロ野球ヤクルトスワローズ選手による保育園・幼稚園での野球教室について、ご報告させていただきます。\n宮本氏は、子どもたちの運動能力の低下、さらに将来的な野球人口の減少を懸念されており、子どもたちの運動能力の向上のきっかけに、そして少しでも多くの子どもたちに野球を知ってもらいたい、野球人口を増やすきっかけになればとの思いから、園児に対する野球教室をボランティアで協力したいとの提案が区にあり、今月１２日に北品川第二保育園、５歳児１８名を対象に、第１回目が行われました。\n内容は、約１時間、準備体操、スポンジボールとプラスチックバットを使い、２チームに分かれたゲーム形式のもの、サインゲームなどを行い、投げる、打つ、走るなどの遊びを通して野球を存分に楽しんでいました。\n初回を終えて、宮本氏から、これをきっかけに子どもたちが野球を身近に感じて、小学校で野球をやってみたいと思ってもらえたらうれしい、これから１年間、区内保育園・幼稚園を回り、野球の楽しさを伝えていきたいとの提案がありましたので、今後も引き続き、区としても協力していきたいと考えております。"},{"i":165,"speaker":"塚本委員長","text":"本件について、ご質疑ございますか。\n〔「なし」と呼ぶ者あり〕"},{"i":166,"speaker":"塚本委員長","text":"ないようですので、ほかにその他で何かございますか。\n〔「なし」と呼ぶ者あり〕"},{"i":167,"speaker":"塚本委員長","text":"なければ、以上でその他を終了いたします。\nそれでは、本日がこのメンバーによる最後の委員会となりますので、正副委員長からご挨拶をさせていただきます。\n伊藤副委員長からお願いいたします。"},{"i":168,"speaker":"伊藤副委員長","text":"今年１年お疲れさまでございました。最後の最後に来て、とても大きなものございましたけれども、文教委員会としては、子どもたちの教育に、また命の問題に直接かかわったものがありますから、メンバーからも品川区議会の責任として、しっかり対処していきたいと思っております。\nまた、今年１年、皆さんのご理解に心から感謝申し上げます。ありがとうございました。"},{"i":169,"speaker":"塚本委員長","text":"ありがとうございました。\nそれでは、続きまして、私からご挨拶申し上げます。\n１年間、文教委員長の務めを果たさせていただきまして、皆様のご協力を賜りましたこと、誠にありがとうございます。大変に重要な案件がいろいろございました。また報告事項等もたくさんありましたけれども、とにもかくにも予定していた審議をつつがなく終了させていただいたこと、大変に皆様のお力の賜物であると、このように感謝を申し上げるものでございます。本当にありがとうございました。\n以上で本日の予定は全て終了いたしました。\nこれをもちまして、文教委員会を閉会いたします。\n○午後４時２５分閉会"}]});
